def run_wb(*argv) -> str:
    buf = io.StringIO()
    with redirect_stdout(buf):
        cli.main(list(argv))
    return buf.getvalue()


@contextlib.contextmanager
def fd_to_devnull(fd: int):
    """This process's ``fd`` on /dev/null for the block, as `wb … 2>/dev/null` runs (#1308)."""
    saved = os.dup(fd)
    null = os.open(os.devnull, os.O_WRONLY)
    try:
        os.dup2(null, fd)
        yield
    finally:
        os.dup2(saved, fd)
        os.close(saved)
        os.close(null)


def not_merged(*argv) -> str:
    """run_wb for an accept --merge whose merge is refused: exit 5 (cli.NOT_MERGED, #247)."""
    buf = io.StringIO()
    with redirect_stdout(buf):
        try:
            cli.main(list(argv))
        except SystemExit as e:
            if e.code != cli.NOT_MERGED:
                raise
        else:
            raise AssertionError("the accept exited 0, not 5")
    return buf.getvalue()


