    def test_the_review_notice_carries_a_small_diff_and_only_the_stat_of_a_big_one(self):
        # each call Claude makes to fetch the diff re-reads its whole session (2026-11-17)
        from workbench import runner
        self.start("t-show", "ok", "--test", TEST_CMD)
        wait_phase("t-show", {"review"})
        rows, _ = store.read_jsonl(store.home() / "notify.jsonl")
        text = [r["text"] for r in rows if r["task"] == "t-show" and r["kind"] == "review"][-1]
        self.assertIn("the diff (all of it", text)
        self.assertIn("+42", text)                                     # the fake's answer.txt
        task = store.Task("t-show")
        (task.worktree / "big.txt").write_text("x\n" * runner.REVIEW_DIFF_MAX)
        big = runner.review_diff(task)
        self.assertIn("too big to include", big)
        self.assertIn("big.txt", big)
        self.assertNotIn("+x", big)

    def test_a_big_diff_is_never_held_whole_just_to_show_its_stat(self):
        # a 19 MB generated file's patch was captured and decoded whole (a 55 MiB peak) for a
        # 182-character notice (#348, the audit of 1.4)
        import tracemalloc
        from workbench import runner
        self.start("t-huge", "ok", "--test", TEST_CMD)
        wait_phase("t-huge", {"review"})
        task = store.Task("t-huge")
        (task.worktree / "huge.txt").write_text("generated line\n" * 400_000)   # 6 MB
        tracemalloc.start()
        try:
            text = runner.review_diff(task)
            peak = tracemalloc.get_traced_memory()[1]
        finally:
            tracemalloc.stop()
        self.assertIn("too big to include", text)
        self.assertIn("huge.txt", text)
        self.assertLess(peak, 2 * 1024 * 1024)

    def test_after_feedback_the_review_notice_carries_only_what_changed_since(self):
        # the wake after a feedback round carried the whole 14K-character diff again, which
        # Claude already had from the first (2026-11-18)
        from workbench import runner
        self.start("t-since", "ok", "--test", TEST_CMD)
        wait_phase("t-since", {"review"})
        task = store.Task("t-since")
        (task.worktree / "CLAUDE.md.proposed").write_text("# rules\n")
        first = runner.review_diff(task)               # what the feedback round answers
        self.assertIn("the agent proposes this change", first)
        (task.worktree / "fixed.txt").write_text("the fix\n")
        again = runner.review_diff(task)
        self.assertIn("the diff since your last review", again)
        self.assertIn("+the fix", again)
        self.assertNotIn("+42", again)                 # the first round's answer.txt: seen already
        self.assertIn("proposed instruction files: unchanged", again)
        self.assertIn("since your last review: (no changes)", runner.review_diff(task))
        task.set_status(steps=2)                       # a new step is reviewed whole
        self.assertNotIn("since your last review", runner.review_diff(task))

    def test_a_review_after_gc_pruned_the_last_snapshot_carries_the_whole_diff_and_says_why(self):
        # #795 (the second 2026-11-21 audit): nothing reaches the snapshot a review notice
        # recorded, git gc pruned it, and the next notice's diff against it failed: the notice
        # left out the whole diff without a word
        from workbench import runner
        self.start("t-gc", "ok", "--test", TEST_CMD)
        wait_phase("t-gc", {"review"})
        task = store.Task("t-gc")
        runner.review_diff(task)
        tree = task.status["reviewed"]["tree"]
        (task.worktree / "fixed.txt").write_text("the fix\n")
        # its ref pins it since #1198: a tree from before then, or one whose ref went, has none
        gitops.drop_reviews(self.repo, "t-gc")
        subprocess.run(["git", "-C", str(self.repo), "prune", "--expire=now"], check=True)
        self.assertFalse(gitops.has_tree(task.worktree, tree))
        again = runner.review_diff(task)
        self.assertIn("the last review's snapshot is gone (git gc pruned it)", again)
        self.assertIn("the diff (all of it", again)
        self.assertIn("+the fix", again)
        self.assertIn("+42", again)

    def test_periodic_check_ins_are_off_unless_asked_for(self):
        # each wakes Claude over its whole context: 500K of one task's 1.2M (2026-11-17)
        self.start("t-quiet", "ok", "--size", "significant")
        self.assertEqual(store.Task("t-quiet").spec["checkin"], 0)
        self.start("t-loud", "ok", "--size", "significant", "--checkin", "15", "--queue")
        self.assertEqual(store.Task("t-loud").spec["checkin"], 15)

    def test_a_script_made_executable_in_the_task_is_committed_executable(self):
        # #323 (the audit of 1.4, reproduced): the repo said core.filemode=false (its drive
        # distrusts modes: WSL's /mnt/c), so run-tool, 0755 in the task's worktree where it ran,
        # was committed 100644, and a fresh checkout couldn't run it
        subprocess.run(["git", "-C", str(self.repo), "config", "core.filemode", "false"], check=True)
        self.start("t-exec", "ok", "--test", TEST_CMD)
        wait_phase("t-exec", {"review"})
        t = store.Task("t-exec")
        tool = t.worktree / "run-tool"
        tool.write_text("#!/bin/sh\necho ran\n")
        tool.chmod(0o755)
        self.assertIn("new file mode 100755", runner.review_diff(t))  # what Claude reviews
        run_wb("accept", "t-exec", "-m", "feat: run-tool")
        row = subprocess.run(["git", "-C", str(self.repo), "ls-tree", "delegate/t-exec", "run-tool"],
                             capture_output=True, text=True).stdout
        self.assertTrue(row.startswith("100755"), row)                # is what lands

    def test_a_state_dir_that_keeps_no_modes_never_shows_every_file_as_made_executable(self):
        # #683 (Claude's audit of main): on exFAT, NTFS, CIFS or drvfs without metadata every file
        # reads 0755; the task's git kept the repo's core.filemode=true, so the whole tree showed
        # as changed to 100755 and accept committed the flip
        self.start("t-nomodes", "ok", "--test", TEST_CMD)
        wait_phase("t-nomodes", {"review"})
        t = store.Task("t-nomodes")
        for f in ("README.md", "CLAUDE.md"):
            (t.worktree / f).chmod(0o755)                  # as such a file system reads them
        with mock.patch.object(gitops, "_modes_hold", return_value=False):
            self.assertIn("core.filemode=false", gitops._pinned(t.worktree))
            self.assertEqual(gitops.changed(t.worktree).split(), ["??", "answer.txt"])
            self.assertNotIn("old mode", runner.review_diff(t))
            buf = io.StringIO()
            with redirect_stdout(buf), contextlib.suppress(SystemExit):
                cli.main(["doctor"])
            self.assertIn("keeps no file modes", buf.getvalue())
        with mock.patch.object(gitops, "_modes_hold", return_value=None):   # couldn't tell
            self.assertNotIn("core.filemode=false", gitops._pinned(t.worktree))
            self.assertNotIn("core.filemode=true", gitops._pinned(t.worktree))
        gitops._modes_hold.cache_clear()
        self.assertIsNone(gitops._modes_hold(str(Path(self.tmp.name) / "nowhere")))

    def test_a_base_with_paths_differing_only_by_case_is_refused_on_a_case_folding_state_dir(self):
        # #797 (the second 2026-11-21 audit, reproduced on a casefold tmpfs): one file was
        # written for docs/API.md and docs/api.md, the review showed the other as the agent's
        # change, and an edit to one was committed to the other
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        for path, data in (("docs/API.md", b"upper\n"), ("docs/api.md", b"lower\n")):
            # into the index alone: on a disk that folds case (macOS's APFS, #950) the second
            # write was the first file again, and HEAD tracked one of the two
            sha = subprocess.run(["git", "-C", str(self.repo), "hash-object", "-w", "--stdin"],
                                 input=data, check=True, capture_output=True).stdout.decode().strip()
            g("update-index", "--add", "--cacheinfo", f"100644,{sha},{path}")
        g("commit", "-qm", "twins")
        with mock.patch.object(gitops, "_case_folds", return_value=True):
            err = io.StringIO()
            with redirect_stderr(err), self.assertRaises(SystemExit):
                self.start("t-twins", "ok")
            self.assertIn("HEAD tracks paths that differ only by case (docs/API.md and docs/api.md)",
                          err.getvalue())
            self.assertIn("case-sensitive volume", err.getvalue())
            self.assertFalse(store.Task("t-twins").dir.exists())
            wt = Path(self.tmp.name) / "wt"
            with self.assertRaisesRegex(gitops.GitError, "differ only by case"):
                gitops.create_worktree(self.repo, "t-twins", wt)
            self.assertFalse(wt.exists())
            self.assertEqual(g("branch", "--list", "delegate/t-twins").stdout, b"")
        with mock.patch.object(gitops, "_case_folds", return_value=False):   # a case-sensitive one
            self.assertEqual(gitops.case_clash(self.repo, "HEAD", self.repo), "")
        g("rm", "-q", "docs/api.md")
        g("commit", "-qm", "one")
        with mock.patch.object(gitops, "_case_folds", return_value=True):
            self.assertEqual(gitops.case_clash(self.repo, "HEAD", self.repo), "")

    def test_the_agents_own_git_sees_the_worktrees_file_system_as_wbs_git_does(self):
        # #796 (the second 2026-11-21 audit): core.filemode and core.ignorecase were pinned for
        # wb's calls only, so on a file system unlike the repo's the agent's `git status` listed
        # every file as changed to 100755, or a case-only rename as a deletion alone
        self.start("t-pins", "ok")
        wait_phase("t-pins", {"review"})
        t = store.Task("t-pins")
        d = os.path.dirname(os.path.abspath(t.worktree))
        modes, folds = gitops._modes_hold(d), gitops._case_folds(d)
        if modes is None or folds is None:
            self.skipTest("can't tell what the state directory's file system does")
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        self.assertEqual(gitops.fs_pins(t.worktree, differing=True), [])   # nothing to say
        g("config", "core.filemode", str(not modes).lower())   # the repo says otherwise
        g("config", "core.ignorecase", str(not folds).lower())
        env = runner.agent_env(t)
        agent = lambda *a, cwd=t.worktree: subprocess.run(  # noqa
            ["git", *a], cwd=cwd, env=env, capture_output=True, text=True)
        self.assertEqual(agent("config", "--bool", "core.filemode").stdout.strip(), str(modes).lower())
        self.assertEqual(agent("config", "--bool", "core.ignorecase").stdout.strip(), str(folds).lower())
        if modes:
            (t.worktree / "CLAUDE.md").chmod(0o755)
            self.assertIn(" M CLAUDE.md", agent("status", "--porcelain").stdout)
        # never forced on a repository of the test suite's own
        scratch = Path(tempfile.mkdtemp(dir=self.tmp.name))
        subprocess.run(["git", "init", "-q", str(scratch)], check=True)
        subprocess.run(["git", "-C", str(scratch), "config", "core.filemode", str(not modes).lower()],
                       check=True)
        self.assertEqual(agent("config", "--bool", "core.filemode", cwd=scratch).stdout.strip(),
                         str(not modes).lower())

    @unittest.skipIf(gitops._case_folds(tempfile.gettempdir()) is not False,
                     "the temp directory folds case: no mismatch to make")
    def test_a_case_only_rename_and_a_case_twin_land_where_the_repo_says_ignorecase(self):
        # #492 (the audit of 1.90, reproduced): the repo said core.ignorecase=true (made by Git
        # for Windows on /mnt/c, or on macOS) and the task's worktree is on a case-sensitive
        # state directory: the rename showed as a deletion alone, OTHER.PY beside other.py as
        # nothing, and accept committed the deletion and removed the worktree with the new names
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        (self.repo / "other.py").write_text("other\n")
        g("add", "other.py")
        g("commit", "-qm", "other")
        g("config", "core.ignorecase", "true")
        self.start("t-case", "ok", "--test", TEST_CMD)
        wait_phase("t-case", {"review"})
        t = store.Task("t-case")
        (t.worktree / "README.md").rename(t.worktree / "Readme.md")
        (t.worktree / "OTHER.PY").write_text("shouted\n")
        files, shown = gitops.changed(t.worktree), runner.review_diff(t)
        for name in ("Readme.md", "OTHER.PY"):
            self.assertIn(name, files)
            self.assertIn(name, shown)                                # what Claude reviews
        run_wb("accept", "t-case", "-m", "feat: case")
        tree = subprocess.run(["git", "-C", str(self.repo), "ls-tree", "--name-only", "delegate/t-case"],
                              capture_output=True, text=True).stdout.split()
        self.assertIn("Readme.md", tree)                              # is what lands
        self.assertIn("OTHER.PY", tree)
        self.assertIn("other.py", tree)
        self.assertNotIn("README.md", tree)

    def test_a_case_only_rename_on_a_state_dir_that_folds_case_shows_in_the_review_and_lands(self):
        # #656 (reproduced on a case-folding tmpfs): there the task's git runs ignorecase=true and
        # matched Helpers.py in the index to helpers.py on disk; the review showed main.py alone,
        # and accept committed Helpers.py beside a main.py importing helpers. Played here by the
        # same git setting on this file system, where the rename read as a deletion alone
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        (self.repo / "Helpers.py").write_text("X = 1\n")
        (self.repo / "main.py").write_text("import Helpers\n")
        g("add", ".")
        g("commit", "-qm", "helpers")
        self.start("t-fold", "ok", "--test", TEST_CMD)
        wait_phase("t-fold", {"review"})
        t = store.Task("t-fold")
        with mock.patch.object(gitops, "_case_folds", return_value=True):
            before = gitops.mark(t.worktree)
            (t.worktree / "Helpers.py").unlink()        # as the agent did it (Linux's rename
            (t.worktree / "helpers.py").write_text("X = 1\n")  # to a case twin does nothing)
            self.assertEqual(gitops.case_renames(t.worktree), [(b"Helpers.py", b"helpers.py")])
            self.assertNotEqual(gitops.mark(t.worktree), before)        # the runner sees the edit
            (t.worktree / "main.py").write_text("import helpers\n")
            stat = gitops.diff(t.worktree, "HEAD", stat=True)
            self.assertIn("Helpers.py => helpers.py", stat)              # what Claude reviews
            run_wb("accept", "t-fold", "-m", "feat: snake case")
        tree = subprocess.run(["git", "-C", str(self.repo), "ls-tree", "--name-only", "delegate/t-fold"],
                              capture_output=True, text=True).stdout.split()
        self.assertIn("helpers.py", tree)                                # is what lands
        self.assertNotIn("Helpers.py", tree)

    def test_a_proposed_claude_md_is_shown_as_a_diff_and_taken_only_when_claude_says(self):
        # Claude making each CLAUDE.md change itself was a call over its whole context on most
        # tasks (2026-11-18): the agent proposes the file, accept takes it
        for name, flags, kept in (("t-take", ("--take-claude-md",), True), ("t-drop", (), False)):
            self.start(name, "ok", "--test", TEST_CMD)
            wait_phase(name, {"review"})
            t = store.Task(name)
            old = (t.worktree / "CLAUDE.md").read_text()
            (t.worktree / "CLAUDE.md.proposed").write_text(old + "Answers live in answer.txt.\n")
            shown = runner.review_diff(t)
            self.assertIn("the agent proposes this change to CLAUDE.md", shown)
            self.assertIn("+Answers live in answer.txt.", shown)
            self.assertNotIn("CLAUDE.md.proposed", shown.split("the agent proposes")[0])
            out = run_wb("accept", name, "-m", "feat: answer", *flags)
            self.assertIn("took" if kept else "dropped", out)
            files = subprocess.run(["git", "-C", str(self.repo), "show", "--name-only",
                                    "--format=", f"delegate/{name}"], capture_output=True,
                                   text=True).stdout.split()
            self.assertNotIn("CLAUDE.md.proposed", files)
            self.assertEqual("CLAUDE.md" in files, kept)

    def test_a_proposal_for_a_gitignored_claude_md_goes_over_the_checkouts_copy(self):
        # #506 (Claude's audit of 1.90, reproduced): CLAUDE.md gitignored, the agent proposed a
        # change; the review diffed it against nothing, accept --take-claude-md said "took" and
        # `add -A` skipped the ignored file, so the change went with the worktree
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True, text=True).stdout
        (self.repo / ".gitignore").write_text("CLAUDE.md\nAGENTS.md\n")
        g("rm", "-q", "--cached", "CLAUDE.md")
        g("add", ".gitignore")
        g("commit", "-qm", "CLAUDE.md is local")
        old = (self.repo / "CLAUDE.md").read_text()
        self.start("t-ign", "ok")
        wait_phase("t-ign", {"review"})
        t = store.Task("t-ign")
        prop = t.worktree / "CLAUDE.md.proposed"
        prop.write_text(old + "Answers live in answer.txt.\n")
        shown = runner.review_diff(t)
        self.assertIn("+Answers live in answer.txt.", shown)
        self.assertNotIn("+# repo", shown)                 # against the copy the agent read
        out = run_wb("accept", "t-ign", "-m", "feat: answer", "--take-claude-md")
        self.assertIn(f"took the agent's proposed CLAUDE.md: written over {self.repo / 'CLAUDE.md'}", out)
        self.assertEqual((self.repo / "CLAUDE.md").read_text(), old + "Answers live in answer.txt.\n")
        files = g("show", "--name-only", "--format=", "delegate/t-ign").split()
        self.assertNotIn("CLAUDE.md", files)
        self.assertNotIn("CLAUDE.md.proposed", files)
        # where the checkout's copy can't take it (a link, as wb init makes AGENTS.md): refused,
        # the proposal kept, and the way to apply it by hand named
        (self.repo / "AGENTS.md").symlink_to("CLAUDE.md")
        self.start("t-ign2", "ok")
        wait_phase("t-ign2", {"review"})
        t = store.Task("t-ign2")
        prop = t.worktree / "AGENTS.md.proposed"
        prop.write_text("# the agent's\n")
        err = io.StringIO()
        with redirect_stderr(err), self.assertRaises(SystemExit):
            run_wb("accept", "t-ign2", "-m", "feat: answer", "--take-claude-md")
        self.assertIn("git ignores AGENTS.md", err.getvalue())
        self.assertIn(str(prop), err.getvalue())
        self.assertTrue(prop.is_file())
        self.assertTrue((self.repo / "AGENTS.md").is_symlink())
        self.assertIn("dropped the agent's proposed AGENTS.md",
                      run_wb("accept", "t-ign2", "-m", "feat: answer"))

    def test_a_proposal_for_agents_md_linked_to_claude_md_goes_into_claude_md_and_keeps_the_link(self):
        # #871 (Claude's audit of 1.90.24): wb init links AGENTS.md to CLAUDE.md; the agent's
        # AGENTS.md.proposed was diffed against nothing, and --take-claude-md put a plain file
        # over the link, leaving CLAUDE.md, the file Claude Code reads, unchanged
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True, text=True).stdout
        (self.repo / "AGENTS.md").symlink_to("CLAUDE.md")
        g("add", "AGENTS.md")
        g("commit", "-qm", "AGENTS.md links to CLAUDE.md")
        old = (self.repo / "CLAUDE.md").read_text()
        self.start("t-link", "ok")
        wait_phase("t-link", {"review"})
        t = store.Task("t-link")
        (t.worktree / "AGENTS.md.proposed").write_text(old + "Answers live in answer.txt.\n")
        self.assertEqual(runner.proposals(t.worktree),
                         [(t.worktree / "CLAUDE.md", t.worktree / "AGENTS.md.proposed")])
        shown = runner.review_diff(t)
        self.assertIn("the agent proposes this change to CLAUDE.md (as AGENTS.md.proposed", shown)
        self.assertIn("+Answers live in answer.txt.", shown)
        self.assertNotIn("+# repo", shown)                 # a diff, not the whole file as new
        # both names proposed through the link: refused, nothing changed
        (t.worktree / "CLAUDE.md.proposed").write_text(old + "Other.\n")
        self.assertIn("--take-claude-md is refused", runner.review_diff(t))
        err = io.StringIO()
        with redirect_stderr(err), self.assertRaises(SystemExit):
            run_wb("accept", "t-link", "-m", "feat: answer", "--take-claude-md")
        self.assertIn("both propose CLAUDE.md", err.getvalue())
        self.assertTrue((t.worktree / "AGENTS.md").is_symlink())
        (t.worktree / "CLAUDE.md.proposed").unlink()
        out = run_wb("accept", "t-link", "-m", "feat: answer", "--take-claude-md")
        self.assertIn("took the agent's proposed CLAUDE.md", out)
        self.assertEqual(g("show", "delegate/t-link:CLAUDE.md"), old + "Answers live in answer.txt.\n")
        self.assertTrue(g("ls-tree", "delegate/t-link", "AGENTS.md").startswith("120000 "))
        self.assertEqual(g("show", "delegate/t-link:AGENTS.md"), "CLAUDE.md")

    def test_a_proposal_the_project_already_tracks_is_left_alone(self):
        # #321 (the audit of 1.4, reproduced): a CLAUDE.md.proposed committed before the task
        # was settled as the agent's, and accept deleted it, though wb diff never showed it
        draft = self.repo / "docs" / "CLAUDE.md.proposed"
        draft.parent.mkdir(exist_ok=True)
        draft.write_text("the team's draft\n")
        for args in (("add", "docs/CLAUDE.md.proposed"), ("commit", "-qm", "a draft")):
            subprocess.run(["git", "-C", str(self.repo), *args], check=True, capture_output=True)
        self.start("t-draft", "ok", "--test", TEST_CMD)
        wait_phase("t-draft", {"review"})
        t = store.Task("t-draft")
        (t.worktree / "AGENTS.md.proposed").write_text("# the agent's\n")  # a new one is its own
        self.assertEqual([p.name for _, p in runner.proposals(t.worktree)], ["AGENTS.md.proposed"])
        self.assertNotIn("docs/CLAUDE.md", runner.review_diff(t))
        out = run_wb("accept", "t-draft", "-m", "feat: answer")
        self.assertIn("dropped the agent's proposed AGENTS.md", out)
        self.assertNotIn("docs/CLAUDE.md", out)
        tree = subprocess.run(["git", "-C", str(self.repo), "ls-tree", "-r", "--name-only",
                               "delegate/t-draft"], capture_output=True, text=True).stdout.split()
        self.assertIn("docs/CLAUDE.md.proposed", tree)   # still there, as committed
        self.assertNotIn("AGENTS.md.proposed", tree)

    def test_the_review_notice_shows_every_file_accept_would_commit(self):
        # #79 (the 2026-11-18 audit): every *.proposed was left out of the notice, so an ordinary
        # schema.proposed, the only change, read as "no changes" and was committed all the same
        self.start("t-prop", "ok", "--test", TEST_CMD)
        wait_phase("t-prop", {"review"})
        t = store.Task("t-prop")
        (t.worktree / "answer.txt").unlink()
        (t.worktree / "schema.proposed").write_text("draft\n")
        (t.worktree / "CLAUDE.md.proposed").write_text("# rules\n")
        shown = runner.review_diff(t)
        code = shown.split("the agent proposes")[0]
        self.assertIn("schema.proposed", code)
        self.assertIn("+draft", code)
        self.assertNotIn("CLAUDE.md.proposed", code)
        run_wb("accept", "t-prop", "-m", "feat: schema")
        files = subprocess.run(["git", "-C", str(self.repo), "show", "--name-only", "--format=",
                                "delegate/t-prop"], capture_output=True, text=True).stdout.split()
        self.assertIn("schema.proposed", files)          # what the notice showed is what landed
        self.assertNotIn("CLAUDE.md.proposed", files)

