        self.start("t-wall", "stay", "--test", TEST_CMD, "--round-timeout", "10")
        st = wait_phase("t-wall", {"review", "stuck", "failed"}, timeout=60)
        self.assertEqual(st["phase"], "review", st.get("last"))
