    def test_a_file_written_under_an_ignored_path_after_a_reaped_runner_is_claudes(self):
        # #1179's review (2026-11-24): a runner killed without a word never reaches its own mark,
        # so the reap marks the agent gone; unmarked, what Claude writes next was never named
        self.ignore_lib()
        self.start("t-reap", "hang")
        st = running("t-reap")
        t = store.Task("t-reap")
        self.assertIsNone(t.status.get("hands_off_at"))
        os.kill(st["pid"], signal.SIGKILL)
        if sys.platform.startswith("linux"):                 # the kernel takes the agent with it
            self.assertTrue(wait_gone(st["agent_pid"]))
        backdate("t-reap")
        self.assertTrue(cli.reap(t))
        self.assertTrue(t.status.get("hands_off_at"), t.status)
        (t.worktree / "lib").mkdir()
        (t.worktree / "lib" / "helper.py").write_text("def answer():\n    return 42\n")
        (t.worktree / "main.py").write_text("from lib.helper import answer\nprint(answer())\n")
        self.assertEqual(runner.hand_wrote(t), ["lib/helper.py"])

    def test_a_file_the_agent_writes_with_its_shell_under_an_ignored_path_is_named_and_refused_at_accept(self):
        # #1210 (the 2.0 bar loop, 2026-11-24): the agent wrote lib/util.py with
        # `cat > lib/util.py <<EOF` under Python.gitignore's lib/; only edit rows were read, so the
        # report had no NOTE and accept --merge landed main.py importing a module it deleted. The
        # fake's row is `cat > util.py` with `workdir` lib/, as 2.3.2 has the model write it: its
        # workdir dropped, the file was named nowhere and left out again (#1210's third review)
        self.ignore_lib()
        self.start("t-sh", "shellwrite", "--test", TEST_CMD)
        wait_phase("t-sh", {"review"})
        t = store.Task("t-sh")
        self.assertEqual(runner.agent_wrote(t), ["answer.txt", "main.py"])
        self.assertEqual(runner.shell_wrote(t), ["lib/util.py"])
        self.assertIn("NOTE: git ignores files the agent wrote (lib/util.py)", run_wb("report", "t-sh"))
        for cmd in (("next", "t-sh", "--spec", "-", "-m", "feat: one"),
                    ("accept", "t-sh", "-m", "feat: one", "--merge")):
            err = io.StringIO()
            with self.assertRaises(SystemExit), redirect_stderr(err), \
                    mock.patch("sys.stdin", io.StringIO("Step two.")):
                run_wb(*cmd)
            self.assertIn("not committed: git ignores files written in the worktree (lib/util.py)",
                          err.getvalue())
            self.assertEqual(self.branch("delegate/t-sh"), t.spec["base"])     # nothing committed
            self.assertTrue((t.worktree / "lib" / "util.py").is_file())        # and the work kept
        self.assertIn("accepted t-sh", run_wb("accept", "t-sh", "-m", "feat: one", "--merge", "--include"))
        tree = subprocess.run(["git", "-C", str(self.repo), "ls-tree", "-r", "--name-only", "main"],
                              capture_output=True, text=True).stdout.split()
        self.assertIn("lib/util.py", tree)
        self.assertIn("main.py", tree)

    def test_a_feedback_rounds_change_to_an_ignored_file_the_agent_wrote_is_in_the_diff_since_the_last_review(self):
        # #1259 (the 2.0 bar loop, 2026-11-24): in a feedback round the agent changed lib/util.py,
        # under Python.gitignore's lib/; the review notice said "the diff since your last review:
        # (no changes)" beside round 1's NOTE word for word, and --include committed code Claude
        # never saw. The snapshot and the diffs held only what git doesn't ignore
        self.ignore_lib()
        self.start("t-fb", "shellwrite", "--test", TEST_CMD)
        wait_phase("t-fb", {"review"})
        t = store.Task("t-fb")
        review = lambda: [r["text"] for r in store.notices()  # noqa: E731
                          if r["task"] == "t-fb" and r["kind"] == "review"]
        first = review()[-1]
        self.assertIn("+++ b/lib/util.py", first)                 # round 1's whole diff holds it
        self.assertIn("NOTE: git ignores files the agent wrote (lib/util.py): the diff shows them", first)
        run_wb("feedback", "t-fb", "--text", "1. main.py: add a docstring.")
        wait_phase("t-fb", {"review"})
        second = review()
        self.assertEqual(len(second), 2)
        self.assertIn("the diff since your last review", second[-1])
        self.assertNotIn("(no changes)", second[-1])
        self.assertIn("+# changed in round 2", second[-1])
        self.assertNotIn("+from lib.util import answer", second[-1])  # main.py: seen already
        self.assertIn("+# changed in round 2", run_wb("diff", "t-fb"))  # wb diff's "all of it" too
        self.assertIn("since your last review: (no changes)", runner.review_diff(t))

    def test_wb_verify_and_wb_shot_run_the_candidate_with_the_ignored_files_accept_commits(self):
        # #1275 (the 2.0 bar loop, 2026-11-24): #1259 put the agent's lib/util.py, under
        # Python.gitignore's lib/, in the review diff but not in verify's candidate: wb verify
        # said "the candidate fails it" (ModuleNotFoundError: lib) for a change that passed in
        # the worktree, wb shot's candidate lacked it, and an edit to it left the check fresh
        from workbench import verify
        self.ignore_lib()
        self.start("t-v", "shellwrite", "--test", TEST_CMD)
        wait_phase("t-v", {"review"})
        t = store.Task("t-v")
        test = "python3 main.py | grep -qx 42 && grep -qx 42 answer.txt"
        out = run_wb("verify", "t-v", "--test", test, "--files", "answer.txt")
        self.assertNotIn("the candidate fails it", out)
        r = verify.last(t)
        self.assertEqual(r["candidate"]["exit"], 0, Path(r["dir"], "candidate.txt").read_text())
        self.assertFalse(r["stale"])
        (t.worktree / "lib" / "util.py").write_text("def answer():\n    return 41\n")
        self.assertTrue(verify.last(t)["stale"])                  # the ignored file it ran on moved
        shot = verify.shot(t, "test -f lib/util.py", ["answer.txt"])
        self.assertEqual(shot["candidate"]["exit"], 0)            # wb shot's candidate holds it too
        self.assertNotEqual(shot["base"]["exit"], 0)              # and the base doesn't

    def test_what_the_runners_test_run_writes_under_an_ignored_path_is_not_taken_for_the_agents(self):
        # #1210 (2026-11-24): read since the agent's first round, a Maven run's surefire report
        # (.xml, a kind pom.xml makes the repo's) would refuse every accept of such a task
        (self.repo / ".gitignore").write_text("target/\n")
