        self.assertIn("the setup command failed (exit 1)", note["text"])
        self.assertFalse((t.worktree / "gen").exists())        # undone, though the setup failed
        self.assertEqual((t.worktree / "Gemfile.lock").read_text(), "GEM\n  pkg (1.0)\n")
