    def test_queued_tasks_run_their_setups_and_base_checks_one_at_a_time_in_queue_order(self):
        # #590, the audit of 1.90: every queued runner ran its setup and base check at once,
        # before the GPU lease: N installs and N test suites together, and a test server on a
        # fixed port failed in all but one clone
        log = Path(self.tmp.name) / "turns.log"
        step = lambda who, what: f"echo {what}-{who} >> {log}"  # noqa: E731
        for who in ("a", "b", "c"):
            self.start(f"t-q{who}", "ok", "--no-self-review", "--queue", "--setup",
                       f"{step(who, 'setup')}; sleep 1; {step(who, 'setup-done')}",
                       "--test", f"{step(who, 'check')}; sleep 0.5; {step(who, 'check-done')}; "
                                 f"test -f answer.txt")
        for who in ("a", "b", "c"):
            wait_phase(f"t-q{who}", {"review"}, timeout=60)
        # each line's first time is the setup or the base check: the round's tests, later,
        # run when they run
        lines = list(dict.fromkeys(log.read_text().split()))[:12]
        # each setup whole before another's begins, each base check the same, a, b, c in order;
        # a setup beside another task's base check is allowed (#868)
        for kind in ("setup", "check"):
            mine = [x for x in lines if x.split("-")[0] == kind]
            opened = []
            for x in mine:
                what, who = x.rsplit("-", 1)
                if what.endswith("-done"):
                    self.assertEqual(opened.pop(), who, mine)
                else:
                    self.assertEqual(opened, [], mine)       # no other of its kind meanwhile
                    opened.append(who)
            self.assertEqual([x.rsplit("-", 1)[1] for x in mine[::2]], ["a", "b", "c"])
        for name in ("prepare.json", "prepare-check.json"):
            self.assertEqual(json.loads((store.home() / "locks" / name).read_text()), {})

    def test_a_base_check_never_waits_behind_another_tasks_long_setup(self):
        # #868 (the third 2026-11-21 audit): one queue held a 5-second base check, capped at
        # 120 s, behind another task's 25-minute build, with the GPU idle meanwhile
        log = Path(self.tmp.name) / "turns.log"
        self.start("t-build", "ok", "--no-self-review", "--queue", "--setup",
                   f"sleep 8; echo build-done >> {log}")
        deadline = time.time() + 10
        while "setting up" not in str(store.Task("t-build").status.get("last")) and time.time() < deadline:
            time.sleep(0.1)
        self.start("t-quick", "ok", "--no-self-review", "--queue", "--test",
                   f"echo check-done >> {log}; test -f answer.txt")
        wait_phase("t-quick", {"review"}, timeout=60)
        wait_phase("t-build", {"review"}, timeout=60)
        lines = log.read_text().split()                       # (the round's tests log too)
        self.assertLess(lines.index("check-done"), lines.index("build-done"), lines)

    def test_fanned_out_tasks_run_their_round_tests_one_at_a_time(self):
        # #1378 (2026-11-25): two tasks of a fan-out ran their round tests at once, and a suite
        # on a fixed port failed EADDRINUSE in all but one: a FAIL and an auto-fix for correct
        # code. The directory stands in for the port: taken while one suite runs.
        held = Path(self.tmp.name) / "port-3000"
        suite = f"mkdir {held} || exit 98; sleep 2; rmdir {held}; {TEST_CMD}"
        for who in ("a", "b"):
            self.start(f"t-fan{who}", "ok", "--no-self-review", "--no-base-check", "--auto-fix", "0",
                       "--test", suite)
        for who in ("a", "b"):
            wait_phase(f"t-fan{who}", {"review"}, timeout=60)
            st = store.Task(f"t-fan{who}").status
            self.assertTrue(st["tests"]["ok"], st["tests"])
            self.assertEqual(st.get("auto_fixes", 0), 0)
        self.assertEqual(json.loads((store.home() / "locks" / "prepare-check.json").read_text()), {})

    def test_a_task_whose_setup_failed_is_resumed_and_discarded_never_counts_against_its_model(self):
        # #581, the audit of 1.90: three discards of a lockfile problem scored the model 0/3 and
        # the router passed it by, though its agent never ran a request
        from workbench import models, router, tuning
        flag = Path(self.tmp.name) / "network-back"
        setup = f"test -e {flag} || {{ echo NO-NETWORK; exit 5; }}"
        self.start("t-never", "ok", "--test", TEST_CMD, "--setup", setup)
        wait_phase("t-never", {"failed"})
        note = [r for r in store.notices() if r["task"] == "t-never"][-1]
        self.assertIn("fix it, then wb resume t-never: it sets the worktree up again (the agent "
                      "never ran)", note["text"])
        run_wb("discard", "t-never")
        row = [r for r in store.results() if r["task"] == "t-never"][-1]
        self.assertEqual((row["ran"], row["failed_before"]), (False, "setup"))
        self.assertFalse(tuning.judged(row))
        m = models.resolve(row["model"])
        self.assertEqual(router.score(m, row["size"]).tries, 0)        # nothing held against it
        # resumed once the setup can work: it sets up again, and the agent runs
        self.start("t-back", "ok", "--test", TEST_CMD, "--setup", setup, "--no-self-review")
        wait_phase("t-back", {"failed"})
        flag.touch()
        run_wb("resume", "t-back")
        st = wait_phase("t-back", {"review", "stuck", "failed"})
        self.assertEqual(st["phase"], "review", st.get("last"))
        run_wb("discard", "t-back")
        row = [r for r in store.results() if r["task"] == "t-back"][-1]
        self.assertIs(row["ran"], True)
        self.assertNotIn("failed_before", row)
        self.assertEqual(router.score(m, row["size"]).tries, 1)        # this one ran: it counts
        # rows from before `ran`: not accepted with no token written never ran
        self.assertFalse(tuning.judged({"outcome": "discarded", "tok_out": 0}))
        self.assertTrue(tuning.judged({"outcome": "discarded", "tok_out": 120}))
        self.assertTrue(tuning.judged({"outcome": "accepted", "tok_out": 0}))
        self.assertTrue(tuning.judged({"outcome": "discarded"}))

    def test_a_sparse_checkout_gets_a_sparse_worktree_and_a_sparse_base_check(self):
        # #263 (the audit of 1.2): the worktree held the whole monorepo, and the base check's
        # clone of it too
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        for d in ("app", "huge"):
            (self.repo / d).mkdir()
            (self.repo / d / "f.txt").write_text(d)
        g("add", "app", "huge")
        g("commit", "-qm", "two packages")
        g("sparse-checkout", "set", "app")
        self.assertFalse((self.repo / "huge").exists())
        self.start("t-sparse", "ok", "--test", "test -e app/f.txt && test ! -e huge", "--auto-fix", "0",
                   "--no-self-review")
        st = wait_phase("t-sparse", {"review", "failed"})
        wt = store.Task("t-sparse").worktree
        self.assertTrue((wt / "app" / "f.txt").exists())
        self.assertFalse((wt / "huge").exists())
        self.assertIs(st["base_check"]["ok"], True)                       # its clone is sparse too
        self.assertEqual(st["phase"], "review")
        self.assertNotIn("huge", gitops.changed(wt))                       # not a deletion

    def test_a_new_directory_outside_the_sparse_cone_is_reported_verified_and_accepted(self):
        # #493 (the audit of 1.90, reproduced): a file made outside the cone (a new package) made
        # `git add -A -N` exit 1, the round report crashed the runner, and wb diff, verify, next
        # and accept died on the same refusal
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        for d in ("app", "huge"):
            (self.repo / d).mkdir()
            (self.repo / d / "f.txt").write_text(d)
        g("add", "app", "huge")
        g("commit", "-qm", "two packages")
        g("sparse-checkout", "set", "--cone", "app")
        made = "mkdir -p tools && echo helper > tools/helper.py && "  # in the lane, as the agent would
        self.start("t-cone", "ok", "--test", made + TEST_CMD, "--auto-fix", "0", "--no-self-review")
        st = wait_phase("t-cone", {"review", "failed"})
        self.assertEqual(st["phase"], "review", st.get("last"))
        report = run_wb("report", "t-cone")
        self.assertIn("tools/helper.py", report)
        self.assertIn("2 files changed", report)
        self.assertIn("+helper", run_wb("diff", "t-cone"))
        out = run_wb("verify", "t-cone", "--test", "test -f tools/helper.py", "--files", "tools/helper.py")
        self.assertIn("proven", out)
        run_wb("accept", "t-cone", "-m", "feat: a helper")
        tree = subprocess.run(["git", "-C", str(self.repo), "ls-tree", "-r", "--name-only",
                               "delegate/t-cone"], capture_output=True, text=True).stdout.split()
        self.assertIn("tools/helper.py", tree)
        self.assertIn("huge/f.txt", tree)                                  # outside it: not deleted

