    def test_failed_compactions_past_the_handover_limit_are_stuck_and_say_so_never_failed(self):
        # #969: every fresh session reads the same and fails to compact again: HANDOVER_MAX
        # still holds, and the stuck report names the failed compaction
        os.environ["FAKE_REFAIL"] = "1"
        st, evs = self.compaction_failed("t-969m", edit=False, exit_code=1)
        self.assertEqual((st["phase"], st["handovers"]), ("stuck", runner.HANDOVER_MAX))
        self.assertIn(f"handed over to a fresh session {runner.HANDOVER_MAX} times in this round "
                      "without finishing (the last when OpenCode's compaction failed: Compaction "
                      "produced no summary): the step is too big", st["last"])
        self.assertEqual(len(self.runs()), runner.HANDOVER_MAX + 1)
        self.assertNotIn("autofix", [e["kind"] for e in evs])
        rows = [r for r in store.read_jsonl(store.home() / "notify.jsonl")[0] if r["task"] == "t-969m"]
        self.assertEqual([r["kind"] for r in rows if r["kind"] != "checkin"], ["stuck"])

    def stuck_on_failed_compactions(self, name):
        """A task stuck past HANDOVER_MAX, its last session's compaction failed (#969), with
        the next runs ordinary ones."""
        os.environ["FAKE_REFAIL"] = "1"
        st, _ = self.compaction_failed(name, edit=False, exit_code=1)
        self.assertEqual(st["phase"], "stuck")
        dead = st["session"]
        self.assertTrue(dead)                                   # the dead session is still current
        for k in ("FAKE_REFAIL", "FAKE_COMPACT_EXIT"):
            os.environ.pop(k, None)
        os.environ["FAKE_SCENARIO"] = "ok"
        return dead

    def assert_the_next_run_is_handed_to_a_fresh_session(self, dead):
        last = self.runs()[-1]
        self.assertFalse(last["session"])                       # not --session <dead>
        self.assertTrue(last["prompt"].startswith("You are picking this task up in a fresh "
                                                  "session (OpenCode failed to compact the last "
                                                  "session)"), last["prompt"][:200])
        self.assertNotIn(dead, json.dumps(last))

    def test_feedback_after_failed_compactions_past_the_limit_goes_to_a_fresh_session(self):
        # #969 (review, 2026-11-21): stuck past HANDOVER_MAX, the dead session stayed in status
        # `session`; wb feedback clears `context`, the export counts only completed compactions
        # and no_room held with nothing changed, so the feedback round went back to the session
        # whose compaction failed, and failing again there (or a context-length exit 1) failed
        # the task, the #969 outcome
        dead = self.stuck_on_failed_compactions("t-969f")
        run_wb("feedback", "t-969f", "--message", str(self.feedback))
        st = wait_phase("t-969f", {"review", "stuck", "failed"}, timeout=60)
        self.assertEqual(st["phase"], "review")
        self.assert_the_next_run_is_handed_to_a_fresh_session(dead)
        self.assertIn("1. Add a trailing comment line.", self.runs()[-1]["prompt"].split("## Now")[1])

    def test_feedback_keeping_the_context_after_failed_compactions_still_goes_to_a_fresh_session(self):
        # #969: a session whose compaction failed can't be kept, --keep-context or not
        dead = self.stuck_on_failed_compactions("t-969g")
        run_wb("feedback", "t-969g", "--message", str(self.feedback), "--keep-context")
        st = wait_phase("t-969g", {"review", "stuck", "failed"}, timeout=60)
        self.assertEqual(st["phase"], "review")
        self.assert_the_next_run_is_handed_to_a_fresh_session(dead)

    def test_next_after_failed_compactions_goes_to_a_fresh_session_and_says_why(self):
        # #969 (review, 2026-11-21): wb next clears `context` too, and said "to the same
        # session" for the dead one. wb next takes a step under review, so the stuck task is put
        # there by hand: what the next step's fresh_reason makes of the dead session is the test
        dead = self.stuck_on_failed_compactions("t-969n")
        store.Task("t-969n").set_status(phase="review")
        step2 = Path(self.tmp.name) / "step2.md"
        step2.write_text("Now also write the question to question.txt.\n")
        out = run_wb("next", "t-969n", "--spec", str(step2), "-m", "feat: step one")
        self.assertIn("to a fresh session (OpenCode failed to compact the last session)", out)
        st = wait_phase("t-969n", {"review", "stuck", "failed"}, timeout=60)
        self.assertEqual(st["phase"], "review")
        self.assert_the_next_run_is_handed_to_a_fresh_session(dead)
        self.assertIn("question.txt", self.runs()[-1]["prompt"])

    def test_a_round_run_again_after_its_server_died_goes_on_in_its_session_without_its_prompt_again(self):
        # #1235 (bar loop round 4, 2026-11-24): a round run again after its server went away sent
        # prompt.md again with --session, and OpenCode keeps a failed run's message: the session
        # held the round's instructions twice (a 402 recheck's, once per recheck). A session that
        # holds them, and round 1's work, is told only to carry them out
        from workbench import transcript
        self.start("t-1235", "ok", "--test", TEST_CMD, "--no-self-review")
        wait_phase("t-1235", {"review"})
        with mock.patch.object(cli, "spawn_runner"):
            run_wb("feedback", "t-1235", "--message", str(self.feedback))
        task = store.Task("t-1235")
        session = task.status["session"]
        os.environ["FAKE_EXIT"] = "1"                 # killed after the model's first words
        before = len(self.runs())
        gone = lambda m: "FAKE_EXIT" in os.environ and len(self.runs()) > before  # noqa: E731
        try:                                          # its server gone under the round, then back
            with mock.patch.object(runner, "_down", side_effect=gone), \
                    mock.patch.object(runner, "_stopped", return_value=False), \
                    mock.patch.object(runner, "_wait_up",
                                      side_effect=lambda t, m: (os.environ.pop("FAKE_EXIT"), m)[1]):
                runner.drive(task)
        finally:
            runner._end_agent(task)
            task.set_status(pid=None)
            runner.CURRENT.clear()
        st = task.status
        self.assertEqual((st["phase"], st["round"], st["session"]), ("review", 2, session), st)
        self.assertIsNone(st.get("unanswered"))
        feedback, again = self.runs()[-2:]
        self.assertEqual((feedback["session"], again["session"]), (True, True))
        self.assertIn("Add a trailing comment line.", feedback["prompt"])
        self.assertEqual(again["prompt"], runner.RERUN)
        self.assertEqual(transcript._user_message(runner.RERUN, False)[0],
                         "workbench → agent · the round again, after its provider or server stopped it")

    def test_a_note_sent_while_the_server_was_down_reaches_the_round_run_again_after_rerun(self):
        # the review of #1235 (2026-11-24): a note `wb steer` queued while the round waited to
        # run again was folded into prompt.md by _early_notes and counted delivered, then RERUN
        # replaced prompt.md whole: the agent never got it. It goes after RERUN, once
        self.start("t-n1235", "ok", "--test", TEST_CMD, "--no-self-review")
        wait_phase("t-n1235", {"review"})
        with mock.patch.object(cli, "spawn_runner"):
            run_wb("feedback", "t-n1235", "--message", str(self.feedback))
        task = store.Task("t-n1235")
        os.environ["FAKE_EXIT"] = "1"                 # killed after the model's first words
        before = len(self.runs())
        gone = lambda m: "FAKE_EXIT" in os.environ and len(self.runs()) > before  # noqa: E731

        def up(t, m):                                 # back, and a note came in meanwhile
            os.environ.pop("FAKE_EXIT")
            store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "text": "NOTE-1235: also say 42."})
            return m
        try:
            with mock.patch.object(runner, "_down", side_effect=gone), \
                    mock.patch.object(runner, "_stopped", return_value=False), \
                    mock.patch.object(runner, "_wait_up", side_effect=up):
                runner.drive(task)
        finally:
            runner._end_agent(task)
            task.set_status(pid=None)
            runner.CURRENT.clear()
        feedback, again = self.runs()[-2:]
        self.assertEqual((feedback["session"], again["session"]), (True, True))
        self.assertNotIn("NOTE-1235", feedback["prompt"])
        self.assertTrue(again["prompt"].startswith(runner.RERUN + "\n\n"), again["prompt"])
        self.assertEqual(again["prompt"].count("NOTE-1235: also say 42."), 1, again["prompt"])
        self.assertNotIn("Add a trailing comment line.", again["prompt"])   # the round's, not again
        self.assertEqual(task.status.get("steer_taken"), 1)

    def test_a_fresh_round_run_again_after_its_server_died_is_handed_over_once(self):
        # #780 (the second 2026-11-21 audit): a round that began fresh, revived before its first
        # event, ran _start_fresh again: the handoff went over instructions.md and was wrapped in
        # a second one, the spec and the diff twice, and a second `fresh` event was logged
        from workbench import lessons
        self.start("t-780", "ok", "--test", TEST_CMD)
        wait_phase("t-780", {"review"})
        task = store.Task("t-780")
        feedback = lessons.FEEDBACK_HEAD + " 1. Add a trailing comment line."
        task.round_dir(2).mkdir(parents=True)
        task.round_dir(2).joinpath("prompt.md").write_text(feedback)
        task.set_status(round=2, context="full", full_pct=76)
        runner._start_fresh(task, 2, runner.fresh_reason(task))
        first = task.round_dir(2).joinpath("prompt.md").read_text()
        # the revive: no session began, and notes came in meanwhile
        self.assertEqual(runner.fresh_reason(task), "the last session ended before it began")
        store.append_jsonl(task.dir / "steer.jsonl", {"ts": store.now(), "text": "Use tabs."})
        runner._early_notes(task, 2)
        runner._start_fresh(task, 2, runner.fresh_reason(task))
        again = task.round_dir(2).joinpath("prompt.md").read_text()
        kept = task.round_dir(2).joinpath("instructions.md").read_text()
        self.assertTrue(kept.startswith(feedback), kept[:200])
        self.assertNotIn("picking this task up", kept)
        self.assertIn("Use tabs.", kept)
        self.assertEqual(again.count("You are picking this task up"), 1)
        self.assertEqual(again.count("## The task"), first.count("## The task"))
        self.assertTrue(again.startswith("You are picking this task up in a fresh session (the "
                                         "last session was 76% full)"), again[:200])
        self.assertIn("Use tabs.", again)
        self.assertTrue(store.round_prompt(task, 2).read_text().startswith(feedback))
        fresh = [e for e in store.read_jsonl(task.dir / "events.jsonl")[0] if e.get("kind") == "fresh"]
        self.assertEqual(len(fresh), 1)

