        clip = "\x1b]52;c;cm0gLXJmIH4=\x07"  # OSC 52: sets the clipboard (the 2026-11-16 audit)
        data = {"messages": [{"type": "assistant", "id": "m1", "finish": "stop", "time": {"created": 1000},
                              "content": [{"type": "text", "text": f"done {clip} \x9b2J"}]}]}
