        for argv in (["answer", "t-big", "--file", str(big)],
                     ["allow", "t-big", "make *", "--text", big.read_text()]):
            err = io.StringIO()
            with redirect_stderr(err), self.assertRaises(SystemExit):
                run_wb(*argv)
