    def test_a_question_the_runner_drops_is_closed_and_wb_answer_refuses_it(self):
        # one that timed out, or whose round ended, kept looking open: Claude was woken for it
        # and `wb answer` said "answered" to nobody (the 0.90 review)
        self.start("t-drop", "ok", "--ask-budget", "3")
        wait_phase("t-drop", {"review"})
        task, opened = store.Task("t-drop"), {}
        task.set_status(phase="running")
        self.agent_asks(task, "aaaaaaaa", question="first?")
        ask_mcp.relay(task, opened)
        ask_mcp._WAITS[(str(task.dir), "aaaaaaaa")].secs = 1201   # past the ask timeout
        ask_mcp.relay(task, opened)
        self.assertEqual((task.status["phase"], opened), ("running", {}))
        self.assertEqual((context.ask_dir(task) / "aaaaaaaa.answer").read_text().strip(),
                         ask_mcp.NO_ANSWER)
        err = io.StringIO()
        with redirect_stderr(err), self.assertRaises(SystemExit):
            run_wb("answer", "t-drop", "--id", "aaaaaaaa", "--text", "late")
        self.assertIn("closed", err.getvalue())
        self.agent_asks(task, "bbbbbbbb", question="second?")
        ask_mcp.relay(task, opened)
        ask_mcp.close(task, opened)                          # its round ended (run_round)
        self.assertFalse(ask_mcp.is_open(task, "bbbbbbbb"))
        from workbench import lessons
        self.assertFalse(any("first?" in r["text"] for r in lessons.gather(task, "accepted")))

    def test_two_answers_at_once_deliver_one_and_an_answer_racing_the_close_is_refused(self):
        # #938 (the outside review of 1.90.24): is_open, then write_answer, with nothing making
        # them one step: two answers both said "answered", the second replacing the first, and
        # one landing as the runner closed the question overwrote NO_ANSWER and was counted
        self.start("t-race", "ok", "--ask-budget", "3")
        wait_phase("t-race", {"review"})
        task, opened = store.Task("t-race"), {}
        task.set_status(phase="running")
        self.agent_asks(task, "aaaaaaaa", question="first?")
        ask_mcp.relay(task, opened)
        real, results = ask_mcp.write_answer, []
        def slow(*a):  # noqa: E306  the window between the check and the write, held open
            time.sleep(0.3)
            real(*a)
        with mock.patch.object(ask_mcp, "write_answer", slow):
            racers = [threading.Thread(target=lambda t=t: results.append(
                (t, ask_mcp.answer_once(task, "aaaaaaaa", t)))) for t in ("one", "two")]
            for r in racers:
                r.start()
            for r in racers:
                r.join()
        self.assertEqual(sorted(ok for _, ok in results), [False, True])
        winner = next(t for t, ok in results if ok)
        self.assertEqual((context.ask_dir(task) / "aaaaaaaa.answer").read_text().strip(), winner)
        self.agent_asks(task, "bbbbbbbb", question="second?")
        ask_mcp.relay(task, opened)
        before = task.status.get("answered")
        once = [dict(opened)]  # the runner's close lands once, between wb answer's check and its write
        closing = lambda text: once and ask_mcp.close(task, once.pop()) or ""  # noqa: E731
        err = io.StringIO()
        with mock.patch.object(ask_mcp, "too_long", closing), redirect_stderr(err), \
                self.assertRaises(SystemExit) as cm:
            run_wb("answer", "t-race", "--id", "bbbbbbbb", "--text", "late")
        self.assertNotEqual(cm.exception.code, 0)
        self.assertIn("already answered (or closed with NO_ANSWER)", err.getvalue())
        self.assertEqual((context.ask_dir(task) / "bbbbbbbb.answer").read_text().strip(),
                         ask_mcp.NO_ANSWER)
        self.assertEqual(task.status.get("answered"), before)

    def test_a_suspend_while_the_agent_waits_on_its_question_does_not_expire_it(self):
        # #453: both waits ran on the wall clock, so a laptop woken past the ask timeout found
        # the question answered "No answer arrived in time" and closed, while the round paused
        self.start("t-susp", "ok")
        wait_phase("t-susp", {"review"})
        task, clock = store.Task("t-susp"), [time.time()]
        fake = types.SimpleNamespace(time=lambda: clock[0], monotonic=lambda: clock[0])
        waits = []

        class Watch:  # the server's waits: a suspend first, then Claude's answer
            def __init__(self, d):
                self.d = d

            def wait(self, secs):
                waits.append(secs)
                if len(waits) == 1:
                    clock[0] += 5000
                else:
                    qid = next(context.ask_dir(task).glob("*.json")).stem
                    ask_mcp.write_answer(task, qid, "Use 42.")

            def close(self):
                pass
        with mock.patch.object(ask_mcp, "time", fake), mock.patch.object(ask_mcp, "Watcher", Watch):
            self.assertEqual(ask_mcp.ask(task, "41 or 42?"), "Use 42.")
            self.assertLessEqual(max(waits), ask_mcp.STEP_SECS)
            task.set_status(phase="running")
            opened = {}
            self.agent_asks(task, "cccccccc", question="again?")
            ask_mcp.relay(task, opened)                     # the runner's side
            clock[0] += 5000                                # suspended
            ask_mcp.relay(task, opened)
            self.assertEqual(list(opened), ["cccccccc"])
            self.assertEqual(task.status["asking"], "cccccccc")
            for _ in range(41):                             # 1230 s awake, in steps
                clock[0] += 30
                ask_mcp.relay(task, opened)
            self.assertEqual(opened, {})                    # then it does time out

    def test_a_stop_closes_the_question_the_agent_waits_on(self):
        # wb stop (or a signal) unwound past run_round's close: the question stayed open, status
        # still named it, and `wb answer` said "answered" to nobody (the 0.90 review)
        self.start("t-stopq", "slow")
        task = store.Task("t-stopq")
        deadline = time.time() + 15
        while not task.status.get("session"):
            self.assertLess(time.time(), deadline, "the agent never started")
            time.sleep(0.1)
        self.agent_asks(task, "aaaaaaaa", question="first?")
        while task.status.get("asking") != "aaaaaaaa":          # the runner relays it
            self.assertLess(time.time(), deadline + 15, task.status)
            time.sleep(0.1)
        run_wb("stop", "t-stopq")
        self.assertEqual((task.status["phase"], task.status.get("asking")), ("stuck", None))
        self.assertFalse(ask_mcp.is_open(task, "aaaaaaaa"))
        err = io.StringIO()
        with redirect_stderr(err), self.assertRaises(SystemExit):
            run_wb("answer", "t-stopq", "--id", "aaaaaaaa", "--text", "late")
        self.assertIn("closed", err.getvalue())

