    def run_calls(self, name, calls, *extra, before=None, in_lane=True, reads=False):
        """Run real opencode in a task's worktree, in its lane (unless not ``in_lane``: a machine
        without Landlock), against a fake model that makes these tool calls; returns the tool
        results it got back, in order. `before(task)` runs once the task is set up, before
        OpenCode starts. ``reads``: the lane keeps its reads too, as the runner's does."""
        self.start(name, "ok", *extra)
        wait_phase(name, {"review"})
        task = store.Task(name)
        if before:
            before(task)
        with socket.socket() as sock:
            sock.bind(("127.0.0.1", 0))
            port = sock.getsockname()[1]
        out = Path(self.tmp.name) / f"{name}-requests.jsonl"
        server = subprocess.Popen([sys.executable, str(ROOT / "tests" / "capture_llm.py"),
                                   str(port), str(out), json.dumps(calls)])
        self.addCleanup(server.kill)
        env = runner.opencode_env(task)
        layer_path = Path(env["OPENCODE_CONFIG"])
        layer = json.loads(layer_path.read_text())
        layer["provider"] = {"cap": {
            "npm": "@ai-sdk/openai-compatible",
            "options": {"baseURL": f"http://127.0.0.1:{port}/v1", "apiKey": "x"},
            "models": {"cap": {"name": "capture", "tool_call": True,
                               "limit": {"context": 32768, "output": 1024}}}}}
        layer_path.write_text(json.dumps(layer))
        time.sleep(0.5)
        cmd = ["opencode", "run", "--standalone", "--agent", context.AGENT, "-m", "cap/cap", "--auto",
               "--format", "json", "go"]                           # the runner's argv (#1290)
        if in_lane:
            cmd = lane.wrap(context.writable(task), cmd,
                            *((context.readable(task), context.unix_paths(task)) if reads else ()))
        subprocess.run(cmd, cwd=task.worktree, env=env, capture_output=True, timeout=180)
        reqs = [json.loads(line) for line in out.read_text().splitlines()]
        last = max(reqs, key=lambda r: len(r.get("messages", [])))
        answers = [json.dumps(m["content"]) for m in last["messages"] if m.get("role") == "tool"]
        self.assertEqual(len(answers), len(calls), "not every fake call came back")
        return task, answers

    def test_the_prompt_file_the_protocol_names_is_one_the_agent_reads_in_its_lane(self):
        # E11 (#1134): the path every round's protocol names must be one OpenCode reads in the
        # lane with no ask, or the pointer sends a compacted agent to a "Permission denied"
        spec = store.Task("t-sf-lane").round_dir(1) / "prompt.md"
        task, answers = self.run_calls("t-sf-lane", [{"name": "read", "arguments": {"path": str(spec)}}])
        self.assertIn(f"saved in `{spec}`", spec.read_text())
        self.assertIn("Write the answer to answer.txt", answers[0])
        self.assertIn("session is compacted", answers[0])

    def test_the_users_opentelemetry_collector_hears_from_no_agent_unless_commands_json_names_it(self):
        # found by #1205's research (2026-11-24): OpenCode 2.3.2 exports OTLP/HTTP traces and
        # logs to OTEL_EXPORTER_OTLP_ENDPOINT whenever it is set, its "cli starting" record
        # carrying the argv, the round's prompt in it, with OTEL_EXPORTER_OTLP_HEADERS on each
        # request; wb kept both, so with Claude Code's OTel on every agent posted its prompt to
        # the user's collector unasked, and the collector's key was in the agent's shell
        posts = []

        class Collector(http.server.BaseHTTPRequestHandler):
            def do_POST(self):
                n = int(self.headers.get("content-length") or 0)
                posts.append((self.path, dict(self.headers), self.rfile.read(n) if n else b""))
                self.send_response(200)
                self.send_header("content-type", "application/json")
                self.end_headers()
                self.wfile.write(b"{}")

            def log_message(self, *a):
                pass
        collector = ThreadingHTTPServer(("127.0.0.1", 0), Collector)  # listens at once (#950)
        threading.Thread(target=collector.serve_forever, daemon=True).start()
        self.addCleanup(collector.server_close)
        self.addCleanup(collector.shutdown)
        printenv = lambda name: [{"name": "shell", "arguments": {
            "command": "printenv", "workdir": str(store.Task(name).worktree)}}]
        with mock.patch.dict(os.environ, {
                "OTEL_EXPORTER_OTLP_ENDPOINT": f"http://127.0.0.1:{collector.server_address[1]}",
                "OTEL_EXPORTER_OTLP_HEADERS": "x-wb-test=CANARY-HEADER"}):
            _, answers = self.run_calls("t-otel-off", printenv("t-otel-off"), in_lane=bool(lane.abi()))
            time.sleep(3)                                    # OpenCode's batch, had it sent one
            self.assertEqual([p for p, _, _ in posts], [])
            self.assertNotIn("OTEL_", answers[0])            # nor in the agent's shell
            self.assertNotIn("CANARY-HEADER", answers[0])
            # named in commands.json `env`, the endpoint goes through (and the listener hears it)
            Path(os.environ["WB_COMMANDS"]).write_text(json.dumps({"env": ["OTEL_EXPORTER_OTLP_ENDPOINT"]}))
            _, answers = self.run_calls("t-otel-on", printenv("t-otel-on"), in_lane=bool(lane.abi()))
        deadline = time.time() + 15
        while time.time() < deadline and not any(p == "/v1/logs" for p, _, _ in posts):
            time.sleep(0.2)
        self.assertIn("/v1/logs", {p for p, _, _ in posts})
        self.assertIn("OTEL_EXPORTER_OTLP_ENDPOINT", answers[0])
        self.assertFalse([h for _, h, _ in posts if "CANARY-HEADER" in json.dumps(h)])  # not named

    def test_a_handed_skill_named_like_a_personal_one_loads_the_librarys_in_and_out_of_the_lane(self):
        # #515 (the audit of v1.90, reproduced): the app synced a personal `pdf` after the
        # library had one; denied by name, every load of the handed skill failed, unexplained
        home = Path(self.tmp.name) / "home"
        write_skill(home / ".claude" / "skills" / "pdf", "pdf",
                    "Use when CANARY-PERSONAL-PDF.", "CANARY-PERSONAL-BODY\n")
        write_skill(home / ".claude" / "skills" / "mine", "mine", "Use when CANARY-MINE.")
        lib = Path(os.environ["WB_SKILLS"])
        write_skill(lib / "pdf", "pdf", "Use when CANARY-LIBRARY-PDF.", "CANARY-LIBRARY-BODY\n")
        with mock.patch.dict(os.environ, {"HOME": str(home)}):
            for lane_on in (True, False):
                task, answers = self.run_calls(f"t-pdf-{int(lane_on)}", [
                    {"name": "skill", "arguments": {"id": "pdf"}},
                    {"name": "skill", "arguments": {"id": "mine"}}], "--skill", "pdf",
                    in_lane=lane_on)
                rules = json.loads((context.rules_dir(task) / "opencode.json").read_text())
                denied = {r["resource"] for r in rules["permissions"]
                          if r["action"] == "skill" and r["effect"] == "deny"}
                self.assertIn("mine", denied)                   # a personal one: still denied
                self.assertNotIn("pdf", denied)                 # the handed one: not
                self.assertIn("CANARY-LIBRARY-BODY", answers[0], lane_on)
                self.assertNotIn("CANARY-PERSONAL", answers[0], lane_on)
                self.assertNotIn("CANARY-MINE", answers[1], lane_on)

    def test_everyday_tools_run_and_the_rest_waits_for_claude(self):
        wt = str(store.Task("t-cmds").worktree)
        built = Path(tempfile.gettempdir()) / f"wb-built-{os.getpid()}"
        self.addCleanup(lambda: built.unlink(missing_ok=True))
        def shell(cmd):
            return {"name": "shell", "arguments": {"command": cmd, "workdir": wt}}
        _, answers = self.run_calls("t-cmds", [
            shell("ls | wc -l && for f in a b; do echo $f; done"),   # pipes, &&, loops
            shell("python3 -c 'print(6*7)'"),
            shell("curl --version"),                                  # not an everyday tool
            shell("echo $(curl --version)"),                          # not hidden in $(…) either
            shell("pip install --no-index nothing-at-all"),           # a new dependency
            shell(f"printf '#!/bin/sh\\necho built-ok\\n' > {built} && chmod +x {built} "
                  f"&& {built}"),                                     # its own build, by path
            shell("npm install; true"),                               # what the project lists
            shell("npx -y cowsay hi"),                                # fetch a package and run it
        ])
        refused = ["permission.rejected" in a for a in answers]
        self.assertEqual(refused, [False, False, True, True, True, False, False, True], answers)
        self.assertIn("42", answers[1])
        self.assertIn("built-ok", answers[5])

