    def test_probes_output_cap_bounds_the_shell_but_not_the_read_tool_and_no_project_lifts_it(self):
        # the owner's design (2026-11-21, #857): tool_output sized to the window, in the layer
        # and in OPENCODE_CONFIG_CONTENT (RESTATED). Measured on OpenCode 2.3.2: it cuts the
        # shell's output to its last lines; `read` keeps its own 2,000 lines or 50 KB
        fake_probe(Path(self.tmp.name))
        long_code(self.repo)
        run_wb("experiment", "probe", "on")
        lines = 1000  # 42 KB for the shell, under a 32K window whole; 3000 for `read`, past its own limit
        def before(task):
            for f, n in (("big.txt", 3000), ("mid.txt", lines)):
                (task.worktree / f).write_text("".join(f"line {i:05d} {'x' * 30}\n" for i in range(n)))
            # a project's own config, loaded after the layer: it must not lift the cap
            (task.worktree / "opencode.json").write_text(json.dumps(
                {"tool_output": {"max_bytes": 1_000_000, "max_lines": 100_000}}))
        name = "t-cap"
        wt = lambda: str(store.Task(name).worktree)  # noqa: E731
        task, answers = self.run_calls(name, [
            {"name": "read", "arguments": {"path": f"{wt()}/big.txt"}},
            {"name": "shell", "arguments": {"command": "cat mid.txt", "workdir": wt()}}], before=before)
        cap = json.loads((context.rules_dir(task) / "opencode.json").read_text())["tool_output"]
        shell = json.loads(answers[1])
        shell = shell if isinstance(shell, str) else json.dumps(shell)
        self.assertLess(len(shell.encode()), cap["max_bytes"] + 1000)     # cut, with its notice
        self.assertIn(f"of {lines}; full output saved to ", shell)
        self.assertIn(f"line {lines - 1:05d}", shell)                     # the last lines kept
        read = json.loads(answers[0])
        read = read if isinstance(read, str) else json.dumps(read)
        self.assertGreater(len(read.encode()), 2 * cap["max_bytes"])       # read: not bounded by it
        self.assertIn("[Output truncated. Continue reading with offset: ", read)
        self.assertIn("2,000 lines (or 50 KB)", context.EXPERIMENT_NOTES["probe"])

    @unittest.skipUnless(lane.abi(), "needs Landlock")
    @home_outside_the_lane
    def test_writes_and_file_tools_stay_in_the_lane_until_claude_widens_it(self):
        # outside the temp directory, which is in every lane
        outside = Path(tempfile.mkdtemp(dir=Path.home(), prefix=".wb-lane-test-"))
        self.addCleanup(shutil.rmtree, outside, True)
        wt = str(store.Task("t-lane").worktree)
        def shell(cmd):
            return {"name": "shell", "arguments": {"command": cmd, "workdir": wt}}
        _, answers = self.run_calls("t-lane", [
            {"name": "write", "arguments": {"path": f"{outside}/a.txt", "content": "x"}},
            shell(f"touch {outside}/b.txt"),
            shell(f"python3 -c \"open('{outside}/c.txt', 'w')\""),
            shell(f"cd {outside} && ls"),
            {"name": "read", "arguments": {"path": "/etc/passwd", "limit": 1}},
            shell("touch made.txt && rm \"$(mktemp)\" && echo lane-ok"),
        ])
        self.assertIn("external_directory", answers[0])       # the file tools keep to the lane
        self.assertIn("Permission denied", answers[1])        # the kernel refuses the shell
        self.assertIn("Permission denied", answers[2])        # and whatever it runs
        self.assertIn("external_directory", answers[3])       # no working elsewhere
        self.assertNotIn("rejected", answers[4])              # the system stays readable
        self.assertIn("lane-ok", answers[5])                  # the worktree and temp are its own
        self.assertEqual(list(outside.iterdir()), [])
        _, answers = self.run_calls("t-wide", [
            {"name": "write", "arguments": {"path": f"{outside}/a.txt", "content": "x"}},
            shell(f"touch {outside}/b.txt && echo wide-ok")], "--allow-path", str(outside))
        self.assertNotIn("rejected", answers[0])
        self.assertIn("wide-ok", answers[1])

    @home_outside_the_lane
    def test_the_file_tools_read_the_installs_the_agent_runs_but_never_edit_them(self):
        # #521, the audit of 1.90: with a conda env's bin on PATH, `read` on its site-packages got
        # "Permission denied: external_directory", and the only remedy granted writes
        env = Path(tempfile.mkdtemp(dir=Path.home(), prefix=".wb-conda-env-"))
        self.addCleanup(shutil.rmtree, env, True)
        (env / "bin").mkdir()
        lib = env / "lib" / "site-packages" / "pandas"
        lib.mkdir(parents=True)
        (lib / "frame.py").write_text("CANARY_FRAME = 1\n")
        calls = [{"name": "read", "arguments": {"path": str(lib / "frame.py")}},
                 {"name": "grep", "arguments": {"pattern": "CANARY_FRAME", "path": str(lib)}},
                 {"name": "write", "arguments": {"path": str(lib / "frame.py"), "content": "x"}},
                 {"name": "write", "arguments": {"path": str(env / "planted.pth"), "content": "x"}}]
        with mock.patch.dict(os.environ, {"PATH": f"{env / 'bin'}{os.pathsep}{os.environ['PATH']}"}):
            task, answers = self.run_calls("t-ro", calls)
            self.assertIn(str(env), context.read_only(task, context.writable(task)))
        self.assertIn("CANARY_FRAME", answers[0])
        self.assertIn("CANARY_FRAME", answers[1])
        self.assertIn("rejected", answers[2])                  # read, never edited
        self.assertIn("rejected", answers[3])
        self.assertEqual((lib / "frame.py").read_text(), "CANARY_FRAME = 1\n")
        self.assertFalse((env / "planted.pth").exists())

    def test_a_project_config_and_the_users_mcp_servers_lift_nothing(self):
        # the 2026-11-16 audit: an opencode.json in the worktree loaded after the task's layer and
        # its allow-all came last; the user's own MCP servers (a GitHub one with their token)
        # reached every agent
        marker = Path(tempfile.gettempdir()) / f"wb-user-mcp-{os.getpid()}"
        self.addCleanup(lambda: marker.unlink(missing_ok=True))
        server = Path(self.tmp.name) / "user_mcp.py"
        server.write_text(
            "import json, sys\n"
            f"open({str(marker)!r}, 'w').close()\n"
            "for line in sys.stdin:\n"
            "    m = json.loads(line)\n"
            "    if 'id' not in m: continue\n"
            "    r = {'initialize': {'protocolVersion': '2025-06-18', 'capabilities': {'tools': {}},\n"
            "         'serverInfo': {'name': 'u', 'version': '1'}},\n"
            "         'tools/list': {'tools': [{'name': 'leak', 'description': 'x',\n"
            "                                   'inputSchema': {'type': 'object'}}]}}.get(m['method'], {})\n"
            "    print(json.dumps({'jsonrpc': '2.0', 'id': m['id'], 'result': r}), flush=True)\n")
        xdg = Path(self.tmp.name) / "xdg"
        (xdg / "opencode").mkdir(parents=True)
        cfg = {**OPENCODE_CONFIG, "share": "auto", "mcp": {"servers": {"usermcp": {
            "type": "local", "command": [sys.executable, str(server)]}}}}
        # where OpenCode finds it, and not in the temp directory above the worktree, where it
        # would load as a project config (OpenCode reads those in every directory up the tree)
        Path(os.environ["WB_OPENCODE_CONFIG"]).unlink()
        os.environ["WB_OPENCODE_CONFIG"] = str(xdg / "opencode" / "opencode.json")
        (xdg / "opencode" / "opencode.json").write_text(json.dumps(cfg))
        os.environ["XDG_CONFIG_HOME"] = str(xdg)

        def plant(task):
            allow = {"permissions": [{"action": "shell", "resource": "*", "effect": "allow"}]}
            (task.worktree / "opencode.json").write_text(json.dumps(allow))
            (task.worktree / ".opencode").mkdir()
            (task.worktree / ".opencode" / "opencode.json").write_text(json.dumps(allow))
        wt = str(store.Task("t-proj").worktree)
        _, answers = self.run_calls("t-proj", [
            {"name": "shell", "arguments": {"command": "curl --version", "workdir": wt}}],
            before=plant)
        self.assertIn("permission.rejected", answers[0])
        reqs = [json.loads(line) for line in
                (Path(self.tmp.name) / "t-proj-requests.jsonl").read_text().splitlines()]
        tools = {t["function"]["name"] for r in reqs for t in r.get("tools", [])}
        self.assertIn("workbench_ask_reviewer", tools)
        self.assertFalse([t for t in tools if t.startswith("usermcp")], tools)
        self.assertFalse(marker.exists())                     # never started either
        self.assertEqual(runner.claude_files_changed("?? opencode.json\n?? .opencode/x.json\n"),
                         ["opencode.json", ".opencode/x.json"])

    @unittest.skipUnless(lane.abi(), "needs Landlock")
    @home_outside_the_lane
    def test_a_server_commands_json_names_reaches_the_agent_in_its_lane_and_no_other_does(self):
        # #1202 (2026-11-24): the user's own MCP server, named in commands.json, is passed through
        # as written, here in code mode (`codemode: true`): with `execute` denied, OpenCode 2.3.2
        # sends its tools direct all the same. It is run by the agent's OpenCode in the lane: its
        # program under a non-dot home directory read, its writes there refused, SECRET_ENV not in
        # its environment; the unlisted one stubbed
        home = Path(tempfile.mkdtemp(dir=Path.home(), prefix="wb-mcp-test-"))
        self.addCleanup(shutil.rmtree, home, True)
        shutil.copy(ROOT / "tests" / "fake_mcp.py", home / "fake_mcp.py")
        planted = home / "planted"
        command = [sys.executable, str(home / "fake_mcp.py"), "lookup"]
        # and in a project's own venv, run as a module (#1202's review): the venv's python
        # resolves to the base interpreter, so the lane read neither the venv nor the module,
        # the server died at its start, and nothing said so; `broken` dies at its start anyway
        srv = Path(tempfile.mkdtemp(dir=Path.home(), prefix="wb-mcp-venv-"))  # beside, not in, home
        self.addCleanup(shutil.rmtree, srv, True)
        (srv / "pyproject.toml").write_text("[project]\nname = 'fake-mcp-srv'\n")
        subprocess.run([sys.executable, "-m", "venv", "--without-pip", str(srv / ".venv")], check=True)
        site = srv / ".venv" / "lib" / f"python{sys.version_info[0]}.{sys.version_info[1]}" / "site-packages"
        shutil.copy(ROOT / "tests" / "fake_mcp.py", site / "fake_mcp_srv.py")
        in_venv = [str(srv / ".venv" / "bin" / "python"), "-m", "fake_mcp_srv", "schema"]
        # `other` in OpenCode's 1.x shape, mcp.<name>, which 2.3.2 still starts: read in the 2.x
        # shape alone, it was never stubbed and ran in every agent's OpenCode (found here)
        # where the agent's OpenCode reads it too, as the user's global config
        xdg = Path(self.tmp.name) / "xdg"
        (xdg / "opencode").mkdir(parents=True)
        Path(os.environ["WB_OPENCODE_CONFIG"]).unlink()
        os.environ.update(WB_OPENCODE_CONFIG=str(xdg / "opencode" / "opencode.json"),
                          XDG_CONFIG_HOME=str(xdg))
        Path(os.environ["WB_OPENCODE_CONFIG"]).write_text(json.dumps({**OPENCODE_CONFIG, "mcp": {
            "servers": {"docs": {"type": "local", "command": command, "codemode": True},
                        "venv-docs": {"type": "local", "command": in_venv},
                        "broken": {"type": "local", "command": [
                            sys.executable, "-c", "import wb_no_such_module"]}},
            "other": {"type": "local", "command": [*command[:2], "leak"]}}}))
        Path(os.environ["WB_COMMANDS"]).write_text(json.dumps({"mcp": ["docs", "venv-docs", "broken"]}))
        started = Path(self.tmp.name) / "mcp-started"
        os.environ.update(WB_TEST_SECRET_TOKEN="CANARY-SECRET", FAKE_MCP_OUTSIDE=str(planted),
                          FAKE_MCP_STARTED=str(started))
        task, answers = self.run_calls("t-mcp-real", [{"name": "docs_lookup", "arguments": {}}],
                                       reads=True)
        self.assertIn("CANARY-MCP lookup secret=- write=refused", answers[0])
        self.assertIn(str(home), context.readable(task))
        self.assertFalse(planted.exists())
        reqs = [json.loads(line) for line in
                (Path(self.tmp.name) / "t-mcp-real-requests.jsonl").read_text().splitlines()]
        tools = {t["function"]["name"] for r in reqs for t in r.get("tools", [])}
        self.assertIn("docs_lookup", tools)
        self.assertIn("venv-docs_schema", tools)
        self.assertIn(str(srv), context.mcp_roots(task))
        self.assertIn("workbench_ask_reviewer", tools)
        self.assertFalse([t for t in tools if t.startswith("other_")], tools)
        # OpenCode's own log names the one that never connected, and why (the round's note)
        self.assertEqual(runner.mcp_unreached(task, 0),
                         {"broken": "ModuleNotFoundError: No module named 'wb_no_such_module'"})
        self.assertFalse({"execute", "question", "subagent"} & tools)
        self.assertNotIn("leak", started.read_text().split())   # never started either
        self.assertIn("lookup", started.read_text().split())

    def test_a_projects_agents_md_and_skills_reach_the_agent_and_its_config_lifts_nothing(self):
        # #994 (2026-11-22): the rules went again in OPENCODE_CONFIG_CONTENT, whose 120,000 bytes
        # a bare task's nearly filled; past them the fallback shut the project's config out, and
        # AGENTS.md and the project's skills with it. Now it is always shut out, and wb hands those
        # back; the user's global AGENTS.md still loads (a temp XDG_CONFIG_HOME, not the real one)
        xdg = Path(self.tmp.name) / "xdg-994"
        (xdg / "opencode").mkdir(parents=True)
        (xdg / "opencode" / "AGENTS.md").write_text("CANARY-GLOBAL-AGENTS\n")
        os.environ["XDG_CONFIG_HOME"] = str(xdg)
        (self.repo / "AGENTS.md").write_text("CANARY-AGENTS-MD\n")
        write_skill(self.repo / ".claude" / "skills" / "proj", "proj", "Use when CANARY-PROJ-SKILL.",
                    "CANARY-PROJ-BODY\n")
        write_skill(self.repo / ".agents" / "skills" / "group" / "deep", "deep",
                    "Use when CANARY-NESTED-SKILL.")
        (self.repo / "docs").mkdir()
        (self.repo / "docs" / "extra.md").write_text("CANARY-PROJ-INSTR\n")
        marker = Path(self.tmp.name) / "plugin-ran"
        (self.repo / ".opencode" / "plugins").mkdir(parents=True)
        (self.repo / ".opencode" / "plugins" / "p.js").write_text(
            f"import fs from 'fs'; fs.writeFileSync({json.dumps(str(marker))}, 'x');\n"
            "export const P = async () => ({});\n")
        (self.repo / "opencode.json").write_text(json.dumps({
            "instructions": ["docs/extra.md"], "agent": {"build": {"prompt": "CANARY-PROJ-PROMPT"}},
            "permissions": [{"action": "shell", "resource": "*", "effect": "allow"}]}))
        subprocess.run(["git", "-C", str(self.repo), "add", "."], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "the project's own"], check=True)
        Path(os.environ["WB_COMMANDS"]).write_text(json.dumps(       # rules past the old cap
            {"allow": [f"wb-filler-{i} *" for i in range(400)]}))
        wt = str(store.Task("t-994").worktree)
        task, answers = self.run_calls("t-994", [
            {"name": "shell", "arguments": {"command": "curl --version", "workdir": wt}},
            {"name": "skill", "arguments": {"id": "proj"}}])
        env = runner.agent_env(task)
        layer = json.loads(Path(env["OPENCODE_CONFIG"]).read_text())
        self.assertGreater(len(json.dumps(layer["permissions"]).encode()), runner.CONFIG_CONTENT_MAX)
        self.assertNotIn("permissions", json.loads(env["OPENCODE_CONFIG_CONTENT"]))
        self.assertIn("permission.rejected", answers[0])     # the project's allow-all lifts nothing
        self.assertIn("CANARY-PROJ-BODY", answers[1])        # its skill loads
        reqs = [json.loads(line) for line in
                (Path(self.tmp.name) / "t-994-requests.jsonl").read_text().splitlines()]
        text = json.dumps(max(reqs, key=lambda r: len(r.get("tools", []))))
        for seen in ("CANARY-GLOBAL-AGENTS", "CANARY-AGENTS-MD", "CANARY-PROJ-SKILL",
                     "CANARY-NESTED-SKILL", "CANARY-PROJ-INSTR"):
            self.assertTrue(seen in text, seen)              # (not assertIn: a prompt per failure)
        self.assertEqual(text.count("CANARY-AGENTS-MD"), 1)
        self.assertFalse("CANARY-PROJ-PROMPT" in text)       # its agent's prompt isn't OpenCode's
        self.assertFalse(marker.exists())                    # nor does its plugin run

    def test_the_users_own_config_contents_old_style_permission_lifts_no_rule(self):
        # #994's review (2026-11-22): OpenCode 2.3.2 still reads the 1.x `permission` object,
        # turned into rules ahead of the same document's `permissions`; the rules then left
        # OPENCODE_CONFIG_CONTENT for the layer, which loads before it, and a user's own
        # `{"permission": {"*": "allow"}}` there came after the rules and lifted every one
        xdg = Path(self.tmp.name) / "xdg-legacy"   # wb reads the content beside no WB_OPENCODE_CONFIG
        (xdg / "opencode").mkdir(parents=True)
        shutil.copy(os.environ.pop("WB_OPENCODE_CONFIG"), xdg / "opencode" / "opencode.json")
        os.environ.update(XDG_CONFIG_HOME=str(xdg),
                          OPENCODE_CONFIG_CONTENT=json.dumps({"permission": {"*": "allow"}}))
        wt = str(store.Task("t-legacy").worktree)
        task, answers = self.run_calls("t-legacy", [
            {"name": "shell", "arguments": {"command": "curl --version", "workdir": wt}}])
        self.assertIn("permission.rejected", answers[0])
        env = runner.agent_env(task)
        self.assertNotIn("permission", json.loads(env["OPENCODE_CONFIG_CONTENT"]))

