    # The 2026-11-16 audit of the lane. A fake home outside /tmp (which is in the lane), and a task
    # with no runner: these check what the lane holds, and the kernel where it can.
    def fake_home(self) -> Path:
        home = Path(tempfile.mkdtemp(dir=Path.home(), prefix=".wb-lane-test-"))
        self.addCleanup(shutil.rmtree, home, True)
        env = {"HOME": str(home)}
        for v in ("XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_STATE_HOME", "XDG_CACHE_HOME",
                  "CARGO_HOME", "RUSTUP_HOME", "GOPATH", "GNUPGHOME", "CLAUDE_CONFIG_DIR",
                  "CONDA_PREFIX"):
            env[v] = ""
        patcher = mock.patch.dict(os.environ, env)
        patcher.start()
        self.addCleanup(patcher.stop)
        for v in [k for k, val in env.items() if not val]:
            os.environ.pop(v, None)
        return home

    def bare_task(self, name, repo) -> store.Task:
        task = store.Task(name)
        task.dir.mkdir(parents=True)
        (task.dir / "task.json").write_text(json.dumps({"name": name, "repo": str(repo)}))
        return task

    def writable_as(self, kind, task) -> list[str]:
        """context.writable(task) as the lane `kind` draws it: Landlock's splits a toolchain home
        around NOT_WRITABLE's places, Seatbelt's keeps it whole and denies them by path."""
        with mock.patch.object(lane, "kind", lambda: kind):
            return context.writable(task)

    def seatbelt_keeps_out(self, task, places, writes=()):
        """With Seatbelt, each of ``places`` is denied by path (write_denied) or outside the lane,
        and each of ``writes`` written: the 2.1 macOS nightly (2026-11-25) ran the Landlock
        split's assertions under Seatbelt, which keeps a cargo, rustup or nimble home whole."""
        with mock.patch.object(lane, "kind", lambda: "seatbelt"):
            w = [os.path.realpath(q) for q in context.writable(task)]
            denied = context.write_denied(w)

        def written(p):
            real = os.path.realpath(p)
            return any(real == q or context._under(real, q) for q in w) and \
                not any(real == d or context._under(real, d) for d in denied)
        for p in places:
            self.assertFalse(written(p), p)
        for p in writes:
            self.assertTrue(written(p), p)

    def reads_in_lane(self, task, files, extra=()):
        script = ("import sys\nfor f in sys.argv[1:]:\n    try:\n        open(f).read()\n"
                  "        print('read')\n    except PermissionError:\n        print('refused')\n")
        out = subprocess.run(lane.wrap(context.writable(task),
                                       [sys.executable, "-c", script, *map(str, files)],
                                       context.readable(task), *extra),
                             capture_output=True, text=True, timeout=20)
        return out.stdout.split() or [out.stderr]

    def test_the_read_lane_lists_no_link_to_wbs_own_output_when_that_goes_to_dev_null(self):
        # #1308 (2026-11-24): /dev/stderr resolved to /dev/null under `wb verify 2>/dev/null`, so
        # it was listed beside it, and the child, whose fd 2 is a pipe, had its lane refused
        task = self.bare_task("t-fds", self.repo)
        task.worktree.mkdir()
        for fd in (1, 2):
            with fd_to_devnull(fd):
                listed = context.readable(task)
            self.assertIn("/dev/null", listed)
            self.assertEqual([p for p in listed if p in context.FD_LINKS
                              or p.startswith("/dev/fd/")], [], fd)

    @unittest.skipUnless(lane.abi(), "needs Landlock")
    def test_a_read_rule_on_a_pipe_leaves_the_pipe_out_and_still_draws_the_lane(self):
        # #1308 (2026-11-24): a listed /dev/stderr, a pipe in the child, was EBADFD to
        # landlock_add_rule, and the whole lane was refused (exit 126)
        out = subprocess.run(lane.wrap([], [sys.executable, "-c", "print('ran')"],
                                       [sys.prefix, "/usr", "/lib", "/lib64", "/etc", "/dev/stderr"]),
                             stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=20)
        self.assertEqual((out.returncode, out.stdout.strip()), (0, "ran"))

