    WRITE_EACH = textwrap.dedent("""\
        import os, sys
        for p in sys.argv[1:]:
            try:
                os.makedirs(os.path.dirname(p), exist_ok=True)
                with open(p, "a") as f:
                    f.write("planted")
                print("wrote")
            except OSError:
                print("refused")
        """)

