    def test_a_replay_keeps_the_tasks_setup_limit_and_its_gpu_for_tests(self):
        # #735 (the 2026-11-21 audit): each replay's wb start got --setup without
        # --setup-timeout, so a long build stopped at 1800 s on every run, and lost
        # --unload-for-tests, its GPU tests beside the resident model
        from workbench import bench
        self.start("t-long", "ok", "--test", "sh tests/check.sh", "--setup", "true",
                   "--setup-timeout", "5400", "--unload-for-tests")
        wait_phase("t-long", {"review"})
        wt = store.Task("t-long").worktree
        (wt / "tests").mkdir()
        (wt / "tests" / "check.sh").write_text("grep -qx 42 answer.txt\n")
        run_wb("accept", "t-long", "-m", "feat: the answer")
        run_wb("bench", "add", "t-long")
        case = bench.cases()["t-long"]
        self.assertEqual((case["setup_timeout"], case["unload_for_tests"]), (5400, True))

        def argv_of(case):
            argv = []
            with mock.patch.object(cli, "parser") as parser:
                parser.return_value.parse_args.side_effect = lambda a: argv.extend(a) or mock.Mock()
                bench._start_task(case, "m", "bench-x", Path(self.tmp.name), [], {})
            return argv
        argv = argv_of(case)
        self.assertEqual(argv[argv.index("--setup-timeout") + 1], "5400")
        self.assertIn("--unload-for-tests", argv)
        # a case made before they were kept: read from its task, while it lasts
        old = {k: v for k, v in case.items() if k not in ("setup_timeout", "unload_for_tests")}
        argv = argv_of(old)
        self.assertEqual(argv[argv.index("--setup-timeout") + 1], "5400")
        self.assertIn("--unload-for-tests", argv)
        self.assertNotIn("--unload-for-tests", argv_of({**case, "unload_for_tests": False}))

    def test_a_replay_from_a_package_copies_both_the_packages_and_the_roots_node_modules(self):
        # #1158 (bar round 1, 2026-11-24): a case's copies are repo-relative, and wb start reads a
        # --copy from the package first, so a case from packages/app that copied both
        # node_modules/ passed `--copy node_modules` and got the package's twice, never the root's
        from workbench import bench
        work = Path(self.tmp.name) / "checkout"
        for d in ("node_modules", "packages/app/node_modules"):
            (work / d).mkdir(parents=True)
        case = {"name": "c-pkg", "test_cmd": "true", "subdir": "packages/app",
                "copy": ["packages/app/node_modules", "node_modules"]}
        argv = []
        with mock.patch.object(cli, "parser") as parser:
            parser.return_value.parse_args.side_effect = lambda a: argv.extend(a) or mock.Mock()
            bench._start_task(case, "m", "bench-x", work, [], {})
        copies = [argv[i + 1] for i, x in enumerate(argv) if x == "--copy"]
        self.assertEqual(copies, ["node_modules", "../../node_modules"])
        self.assertEqual([cli._copy_path(work, p, "packages/app") for p in copies], case["copy"])
        # from the repo's top they pass as kept
        copies = []
        with mock.patch.object(cli, "parser") as parser:
            parser.return_value.parse_args.side_effect = lambda a: copies.extend(
                a[i + 1] for i, x in enumerate(a) if x == "--copy") or mock.Mock()
            bench._start_task({**case, "subdir": ""}, "m", "bench-x", work, [], {})
        self.assertEqual(copies, case["copy"])

    def test_a_cases_checks_and_every_grade_hold_the_gpu_alone_when_its_tests_need_it(self):
        # #1098 (the 2.0 audit, 2026-11-23): only a replay's own rounds got --unload-for-tests;
        # bench add's base and reference checks, each replay's grade and wb bench self's ran
        # beside resident models, so an out-of-memory failure refused a good case or read as the
        # model's. Each runs inside the GPU hold (media.gpu, through verify.gpu), and a case
        # without the flag waits for no GPU
        from workbench import bench, media
        held, calls = [], []
        real_lane = runner.run_in_lane

        @contextlib.contextmanager
        def gpu(who, say, wait, *a, **k):
            held.append(who)
            yield
            held.pop()

        def lane(task, cmd, *a, **k):
            calls.append((task.name, cmd, bool(held)))
            return real_lane(task, cmd, *a, **k)
        self.start("t-gpu", "ok", "--test", "sh tests/check.sh", "--unload-for-tests")
        wait_phase("t-gpu", {"review"})
        wt = store.Task("t-gpu").worktree
        (wt / "tests").mkdir()
        (wt / "tests" / "check.sh").write_text("grep -qx 42 answer.txt\n")
        run_wb("accept", "t-gpu", "-m", "feat: the answer")
        self.accepted("t-src")
        os.environ["FAKE_SCENARIO"] = "ok"
        self.fake_claude("42")
        with mock.patch.object(media, "gpu", gpu), mock.patch.object(runner, "run_in_lane", lane):
            bench.add("t-gpu")                                     # the base, then the reference
            self.assertEqual(calls, [("t-gpu", "sh tests/check.sh", True)] * 2)
            calls.clear()
            row = bench.replay(bench.cases()["t-gpu"], "ollama/mimo-v2.6:9b-q8_0", 1, "r1", "", [])
            self.assertEqual(row["outcome"], "passed", row)
            self.assertEqual([c[1:] for c in calls], [("sh tests/check.sh", True)])  # its grade
            calls.clear()
            self.assertEqual(bench.self_run("t-gpu")["outcome"], "passed")
            self.assertEqual(calls, [("t-gpu", "sh tests/check.sh", True)])
            calls.clear()
            bench.add("t-src")                                     # no flag: no GPU wait
            row = bench.replay(bench.cases()["t-src"], "ollama/mimo-v2.6:9b-q8_0", 1, "r1", "", [])
            self.assertEqual(row["outcome"], "passed", row)
            self.assertEqual(bench.self_run("t-src")["outcome"], "passed")
            self.assertEqual([c[2] for c in calls], [False] * 4)

    def _flagged_case(self, name: str) -> dict:
        """A bench case whose task ran with --unload-for-tests and a hidden check (#1098)."""
        from workbench import bench
        self.start(name, "ok", "--test", "sh tests/check.sh", "--unload-for-tests")
        wait_phase(name, {"review"})
        wt = store.Task(name).worktree
        (wt / "tests").mkdir()
        (wt / "tests" / "check.sh").write_text("grep -qx 42 answer.txt\n")
        run_wb("accept", name, "-m", "feat: the answer")
        os.environ["FAKE_SCENARIO"] = "ok"
        bench.add(name)
        return bench.cases()[name]

    def test_a_real_task_that_comes_during_a_flagged_grade_stops_it_and_finds_the_gpu_free(self):
        # the review of #1098 (2026-11-23): the grade held the GPU as the replay, so a real task's
        # preempt killed it, the row read `failed` (the model's), and the driver's hold stayed:
        # the real task was refused (exit 4) or queued behind the bench. Now the grade lets go,
        # the row is `preempted` (replayed later), and the real task finds the GPU free
        from workbench import bench, media, models

        @contextlib.contextmanager
        def gpu(who, say, wait, *a, **k):  # the lease alone, without unloading anything
            with models.GpuLease(None, who, say, wait=wait):
                yield
        real_lane, slow, grading = runner.run_in_lane, threading.Event(), threading.Event()

        def lane(task, cmd, *a, **k):
            if slow.is_set():  # the grade: long enough to be preempted in
                grading.set()
                return real_lane(task, f"touch .graded && exec sleep 60; {cmd}", *a, **k)
            return real_lane(task, cmd, *a, **k)
        with mock.patch.object(media, "gpu", gpu), mock.patch.object(runner, "run_in_lane", lane):
            case = self._flagged_case("t-gpu")
            mid = "ollama/mimo-v2.6:9b-q8_0"
            m = models.discover()[mid]
            rows, real = [], {}
            orig_wait = bench._wait

            def waited(task):
                out = orig_wait(task)
                real["task"] = task
                slow.set()
                return out
            with mock.patch.object(bench, "_wait", waited):
                t = threading.Thread(target=lambda: rows.append(
                    bench.replay(case, mid, 1, "r1", "", [])))
                t.start()
                try:
                    self.assertTrue(grading.wait(120))
                    wt = real["task"].worktree
                    deadline = time.time() + 60
                    while not (wt / ".graded").exists() and time.time() < deadline:
                        time.sleep(0.05)
                    self.assertTrue(cli._gpu_wait(m, "real")[1])      # the grade holds the GPU
                    began = time.time()
                    self.assertIn("stopped the bench's replay", cli._preempt_bench(m, "real"))
                    self.assertFalse(cli._gpu_wait(m, "real")[1])     # and has let it go
                    self.assertLess(time.time() - began, 20)
                finally:
                    t.join(120)
        self.assertEqual(rows[0]["outcome"], "preempted", rows[0])

    def test_a_flagged_grade_waits_for_a_free_gpu_without_queueing_ahead_of_real_tasks(self):
        # the review of #1098 (2026-11-23): queued, the grade's place was the replay's created_at,
        # ahead of every real task started after it. It now asks without queueing (wait=False:
        # no gpu.json entry while it waits) and tries again until the GPU is free
        from workbench import bench, media
        asks = []

        @contextlib.contextmanager
        def gpu(who, say, wait, *a, **k):
            asks.append(wait)
            if store.Task(who).spec.get("bench") and len(asks) < 3:
                raise RuntimeError("the GPU is busy")  # a real task holds it twice
            yield
        with mock.patch.object(media, "gpu", gpu), mock.patch.object(bench, "GRADE_POLL", 0.01):
            case = self._flagged_case("t-gpu")
            asks.clear()
            row = bench.replay(case, "ollama/mimo-v2.6:9b-q8_0", 1, "r1", "", [])
        self.assertEqual(row["outcome"], "passed", row)
        self.assertEqual(asks, [False] * 3)

    def test_a_cases_checkouts_read_the_bytes_the_task_read(self):
        # #736 (the 2026-11-21 audit, reproduced by both audits): with the repo's own
        # core.autocrlf the task read CRLF, and bench add's reference check and each replay's
        # clone read LF: the case was refused as failing on its own commit
        from workbench import bench
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        (self.repo / "data.txt").write_bytes(b"a\nb\n")
        g("add", "-A")
        g("commit", "-qm", "data")
        g("config", "core.autocrlf", "true")
        (self.repo / ".git" / "info" / "attributes").write_text("*.sh -text\nanswer.txt -text\n")
        crlf = "python3 -c \"import sys; sys.exit(open('data.txt', 'rb').read() != b'a\\r\\nb\\r\\n')\""
        test = f"{crlf} && sh tests/check.sh"
        self.accepted("t-crlf", test)
        out = run_wb("bench", "add", "t-crlf")
        self.assertIn("on the base: fails", out)
        clone = Path(self.tmp.name) / "c"
        bench.checkout(bench.cases()["t-crlf"], clone)
        self.assertEqual((clone / "data.txt").read_bytes(), b"a\r\nb\r\n")    # a replay's too

    def test_a_filter_whose_key_stays_in_the_git_dir_is_named_by_bench_add_and_a_replay(self):
        # #932's review (reproduced): bench's clones took the repo's filters but not verify's
        # handling: a required git-crypt-like one died on a raw git error naming no setting, and
        # one falling back to the stored bytes refused the case as failing on its own commit
        from workbench import bench
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        key = 'test -f "$(git rev-parse --git-common-dir)/gc-key"'
        g("config", "filter.gc.clean", "sed s/42/SECRET/")
        g("config", "filter.gc.smudge", f"sh -c 'if {key}; then sed s/SECRET/42/; else cat; fi'")
        (self.repo / ".git" / "gc-key").write_text("k\n")
        (self.repo / ".gitattributes").write_text("answer.txt filter=gc\nsecret.txt filter=gc\n")
        g("add", "-A")
        g("commit", "-qm", "a filter keyed in the git dir")
        task = self.accepted("t-gc")
        self.assertEqual(gitops.git(self.repo, "cat-file", "-p",
                                    f"{task.spec['branch']}:answer.txt"), "SECRET\n")
        with self.assertRaisesRegex(RuntimeError, r"answer\.txt checks out differently.*filter\.gc"):
            bench.add("t-gc")                                    # not "fails on its own commit"
        g("config", "filter.gc.required", "true")
        g("config", "filter.gc.smudge", f"sh -c 'if {key}; then sed s/SECRET/42/; else exit 1; fi'")
        with self.assertRaisesRegex(RuntimeError, r"failed in filter\.gc, the repo's own"):
            bench.add("t-gc")                                    # not git's words alone
        # a replay's checkout of a base with such a file: the same, so its error row names it
        (self.repo / "secret.txt").write_text("42\n")
        g("add", "-A")
        g("commit", "-qm", "a filtered file in the base")
        tmp = Path(self.tmp.name)
        bench.bundle(self.repo, "HEAD", tmp / "b.bundle")
        with self.assertRaisesRegex(RuntimeError, r"failed in filter\.gc"):
            bench._clone_base(tmp / "b.bundle", tmp / "c1", self.repo)
        g("config", "--unset", "filter.gc.required")
        g("config", "filter.gc.smudge", f"sh -c 'if {key}; then sed s/SECRET/42/; else cat; fi'")
        with self.assertRaisesRegex(RuntimeError, r"secret\.txt checks out differently"):
            bench._clone_base(tmp / "b.bundle", tmp / "c2", self.repo)
        g("config", "filter.gc.smudge", "sed s/SECRET/42/")          # one that works there: fine
        bench._clone_base(tmp / "b.bundle", tmp / "c3", self.repo)
        self.assertEqual((tmp / "c3" / "secret.txt").read_text(), "42\n")

