        self.assertEqual((f["periods"]["week"]["tasks"], f["periods"]["week"]["landed"]), (4, 3))
        self.assertEqual(f["periods"]["week"]["accepted_pct"], 75)
        self.assertEqual(f["guards"], {"repeat": 2, "silence": 1})
