class UpdatedUnderATask(Base):
    """A clone pulled (or a plugin updated) while a task runs: its runner, on the old code, ends
    the task cleanly before the next round instead of feeding the round new children (#603)."""

    def test_every_module_the_runner_imports_late_is_loaded_before_the_task_starts(self):
        # #1115: main loaded router, transcript and verify up front but not results (every API
        # round's report) nor cli (add_outline's PROTOCOL), so a pull mid-round made the old
        # runner import the new results.py. A fresh interpreter: this one has loaded everything
        import ast
        tree = ast.parse((runner.PKG_ROOT / "workbench/runner.py").read_text())
        late = set()
        for fn in ast.walk(tree):
            if isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)) and fn.name != "load_up_front":
                for node in ast.walk(fn):
                    if isinstance(node, ast.ImportFrom) and node.level == 1:
                        late |= ({node.module} if node.module else {a.name for a in node.names})
        self.assertIn("results", late)                                      # the walk sees them
        code = ("import sys, workbench.runner as r; r.load_up_front(); "
                "print(' '.join(m[10:] for m in sys.modules if m.startswith('workbench.')))")
        out = subprocess.run([sys.executable, "-c", code], cwd=runner.PKG_ROOT, text=True,
                             capture_output=True, check=True).stdout.split()
        self.assertEqual(sorted(late - set(out)), [])

    def test_a_runner_whose_lane_shim_or_ask_code_changed_hands_the_next_round_to_one_on_the_new_code(self):
        # #603: the children load the clone afresh each round. Until #1322 (2026-11-24) the
        # runner stopped the task as stuck and woke Claude for a wb resume that was always the
        # answer: it now execs a runner of the new code, the same pid, which runs the next round
        pkg = Path(self.tmp.name) / "pkg"   # a copy to update: the runner runs from it
        ignore = shutil.ignore_patterns("__pycache__")
        for d in ("workbench", "bin", "agent", "tests"):   # the fake too: the lane reads the copy
            shutil.copytree(runner.PKG_ROOT / d, pkg / d, ignore=ignore)
        os.environ["WB_OPENCODE_BIN"] = shlex.join([sys.executable, str(pkg / "tests/fake_opencode.py")])
        with mock.patch.object(cli, "PKG_ROOT", pkg):
            os.environ["FAKE_SLEEP"] = "2"
            self.start("t", "fix", "--test", TEST_CMD, "--no-base-check")   # round 2 would follow
            running("t")
            with (pkg / "workbench/lane.py").open("a") as f:
                f.write("\n# a pull landed\n")
            st = wait_phase("t", {"review", "stuck", "failed"})
        self.assertEqual((st["phase"], st["round"]), ("review", 2), st.get("last"))
        self.assertTrue(store.Task("t").round_dir(2).joinpath("summary.md").exists())
        loads = [e["text"] for e in store.read_jsonl(store.Task("t").dir / "events.jsonl")[0]
                 if e.get("kind") == "load"]
        self.assertIn("workbench was updated: a runner on the new code carries on", loads)
        notes = [r["kind"] for r in store.read_jsonl(store.home() / "notify.jsonl")[0] if r.get("task") == "t"]
        self.assertNotIn("stuck", notes)
        # #788: a task an older runner stopped so still resumes with --all
        self.assertTrue(cli._interrupted(f"{runner.UPDATED}: wb resume t continues it on the new code"))
        self.assertFalse(cli._interrupted("workbench was updated under this tasking"))

    def test_an_update_or_an_opencode_change_before_a_round_stops_nothing_and_counts_no_review(self):
        # #1176 (2026-11-24): the stop these two made, and the wb feedback its wake advised,
        # counted a review round. Since #1322 neither stops: the update hands the round to a
        # runner of the new code (here the second drive), the 2.x change carries on
        from workbench import results, router, tuning
        for cause in ("updated", "opencode"):
            with self.subTest(cause=cause):
                name = f"t-{cause}"
                with mock.patch.object(cli, "spawn_runner"):
                    self.start(name, "fix", "--test", TEST_CMD, "--auto-fix", "1", "--no-base-check")
                task = store.Task(name)
                ran = lambda: task.round_dir(1).joinpath("summary.md").exists()  # noqa: E731
                # round 1 ran and failed its test; before its auto-fix, a pull or an upgrade
                with mock.patch.dict(runner.CURRENT, {"code": "before"}), \
                        mock.patch.object(runner, "code_print",
                                          lambda: "after" if ran() and cause == "updated" else "before"), \
                        mock.patch.object(runner, "opencode_version",
                                          lambda: (2, 5) if ran() and cause == "opencode" else (2, 3)):
                    runner.drive(task)
                    self.assertEqual(bool(runner.CURRENT.get("successor")), cause == "updated")
                if cause == "updated":
                    self.assertEqual((task.status["phase"], task.status["round"]), ("queued", 2))
                    runner.drive(task)                             # the runner on the new code
                self.assertEqual(task.status["phase"], "review", task.status.get("last"))
                self.assertFalse([r for r in store.read_jsonl(store.home() / "notify.jsonl")[0]
                                  if r["task"] == name and r["kind"] == "stuck"])
                os.environ["FAKE_SCENARIO"] = "ok"
                with mock.patch.object(cli, "spawn_runner"):
                    self.assertIn("feedback round 1 sent", run_wb("feedback", name, "--text", "rename x"))
                runner.drive(task)
                step = results.step(task, True)
                self.assertEqual(tuning.agent_reviews(step), 1)
                self.assertEqual(router._went(step), "well")

    def test_an_unchanged_copy_runs_every_round(self):
        self.start("t", "fix", "--test", TEST_CMD, "--no-base-check")
        st = wait_phase("t", {"review"})
        self.assertTrue(st["tests"]["ok"])


class Update(Base):
    """wb update: the weekly check the mod runs, and /workbench-update (2026-11-16). A real origin
    and clone stand in for this copy; a fake `claude` records the plugin steps."""
    def setUp(self):
        super().setUp()
        tmp = Path(self.tmp.name)
        git = lambda d, *a: subprocess.run(["git", "-C", str(d), *a], check=True, capture_output=True)
        self.origin = tmp / "origin"
        git(tmp, "clone", "-q", str(self.repo), str(self.origin))
        os.environ["CLAUDE_CONFIG_DIR"] = str(tmp / "cc")
        os.environ.pop("CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC", None)  # CI sets it (2026-11-17)
        self.copy = tmp / "cc/plugins/marketplaces/workbench"    # where Claude Code keeps its clone
        git(tmp, "clone", "-q", str(self.origin), str(self.copy))
        (self.origin / "new.txt").write_text("x")
        git(self.origin, "add", "new.txt"); git(self.origin, "commit", "-qm", "news")
        self.calls = tmp / "claude-calls"
        bindir = tmp / "fakebin"; bindir.mkdir()
        (bindir / "claude").write_text(f'#!/bin/sh\necho "$@" >> {self.calls}\n')
        (bindir / "claude").chmod(0o755)
        os.environ["PATH"] = f"{bindir}{os.pathsep}{os.environ['PATH']}"
        patcher = mock.patch.object(cli, "PKG_ROOT", self.copy)
        patcher.start(); self.addCleanup(patcher.stop)

    def update(self, *a):
        buf, err = io.StringIO(), io.StringIO()
        try:
            with redirect_stdout(buf), redirect_stderr(err):
                cli.main(["update", *a])
        except SystemExit:
            pass
        return buf.getvalue() + err.getvalue()

    def test_the_check_counts_new_commits_and_asks_origin_at_most_weekly(self):
        self.assertIn("update available: 1 new commit(s)", self.update("--check", "--if-due"))
        (self.origin / "more.txt").write_text("y")
        subprocess.run(["git", "-C", str(self.origin), "add", "more.txt"], check=True)
        subprocess.run(["git", "-C", str(self.origin), "commit", "-qm", "more"], check=True)
        self.assertIn("1 new commit(s)", self.update("--check", "--if-due"))   # this week's answer
        self.assertIn("1 new commit(s)", self.update("--if-due"))   # it implies --check (#1322): no pull
        self.assertIn("2 new commit(s)", self.update("--check"))               # asked now
        os.environ["CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC"] = "1"
        store.write_json(store.home() / "update.json", {"checked_at": 0, "behind": 2})
        self.assertIn("2 new commit(s)", self.update("--check", "--if-due"))   # no network at all

    def test_the_weekly_answer_follows_a_pull_made_elsewhere(self):
        # the audit: the cached count stood for a week after a hand pull (or Claude Code's own
        # update) had installed the news, and every load toasted it
        self.assertIn("1 new commit(s)", self.update("--check"))
        subprocess.run(["git", "-C", str(self.copy), "pull", "-q", "--ff-only"], check=True)
        self.assertIn("up to date", self.update("--check", "--if-due"))

    def test_the_check_keeps_the_users_ssh_command(self):
        # the audit: GIT_SSH_COMMAND='ssh -o BatchMode=yes' replaced core.sshCommand, so a clone
        # that needs its own key never heard of an update
        marker = Path(self.tmp.name) / "ssh-ran"
        ssh = Path(self.tmp.name) / "myssh"
        ssh.write_text(f"#!/bin/sh\necho \"$@\" > {shlex.quote(str(marker))}\nexit 1\n")
        ssh.chmod(0o755)
        git = lambda *a: subprocess.run(["git", "-C", str(self.copy), *a], check=True)  # noqa
        git("remote", "set-url", "origin", "ssh://git@example.invalid/workbench.git")
        git("config", "core.sshCommand", str(ssh))
        os.environ.pop("GIT_SSH_COMMAND", None)
        self.assertIn("couldn't check for an update", self.update("--check"))
        self.assertIn("example.invalid", marker.read_text())

    def test_without_claude_on_path_an_update_changes_nothing(self):
        # the audit: a clone pulled, then died with a traceback at the claude step
        os.environ["CLAUDE_CONFIG_DIR"] = str(Path(self.tmp.name) / "elsewhere")   # a clone
        only_git = Path(self.tmp.name) / "only-git"
        only_git.mkdir()
        (only_git / "git").symlink_to(shutil.which("git"))
        os.environ["PATH"] = str(only_git)
        self.assertIn("claude isn't on PATH", self.update())
        self.assertFalse((self.copy / "new.txt").exists())

    def test_an_update_moves_opencodes_plugin_to_a_copy_of_the_pulled_commit(self):
        # #1321's findings 16 and N2: OpenCode loads a copy of the clone's committed
        # opencode-plugin/, so the update that pulls a new one moves the entry to its copy
        from workbench import ocplugin
        tmp = Path(self.tmp.name)
        os.environ.update(HOME=str(tmp / "home"), CLAUDE_CONFIG_DIR=str(tmp / "elsewhere"))
        git = lambda d, *a: subprocess.run(["git", "-C", str(d), "-c", "user.name=t", "-c", "user.email=t@t", *a],  # noqa
                                           check=True, capture_output=True)
        (self.origin / "opencode-plugin").mkdir()
        shutil.copy(ROOT / "opencode-plugin/package.json", self.origin / "opencode-plugin/package.json")
        (self.origin / "opencode-plugin/server.ts").write_text("// one\n")
        git(self.origin, "add", "-A"); git(self.origin, "commit", "-qm", "the plugin")
        git(self.copy, "pull", "-q", "--ff-only")
        conf = Path(os.environ["WB_OPENCODE_CONFIG"])
        with mock.patch.object(ocplugin, "PKG_ROOT", self.copy), \
                mock.patch.object(ocplugin, "DIR", self.copy / "opencode-plugin"):
            ocplugin.install()
            first = json.loads(conf.read_text())["plugins"][0]["package"]
            (self.origin / "opencode-plugin/server.ts").write_text("// two\n")
            git(self.origin, "commit", "-qam", "the plugin changed")
            out = self.update()
            second = Path(json.loads(conf.read_text())["plugins"][0]["package"])
        self.assertIn("updated clone ", out)
        self.assertIn(f"→ {second} (was {first})", out)
        self.assertEqual((second / "server.ts").read_text(), "// two\n")
        self.assertFalse(self.calls.exists())                     # OpenCode's alone: no claude step

    def test_a_clone_only_opencodes_plugin_loads_updates_without_claude(self):
        # #1321's findings 4 and 15: wb setup --opencode's clone, which Claude Code doesn't have,
        # was refused without claude ("claude isn't on PATH"), and with claude failed on a
        # marketplace it doesn't know after the pull. Pulled alone; Claude Code's clone as before
        from workbench import ocplugin
        os.environ["CLAUDE_CONFIG_DIR"] = str(Path(self.tmp.name) / "elsewhere")
        conf = Path(os.environ["WB_OPENCODE_CONFIG"])
        cfg = json.loads(conf.read_text())
        (self.copy / "package.json").write_text(json.dumps({"name": ocplugin.PACKAGE}))  # the clone's own
        with mock.patch.object(ocplugin, "PKG_ROOT", self.copy):
            for plugins, loads in (([str(self.copy / "opencode-plugin")], True), ([str(self.copy)], True),
                                   ([{"package": ocplugin.GIT_SPEC, "options": {"wb": str(self.copy / "bin/wb")}}], True),
                                   ([ocplugin.GIT_SPEC], False)):   # OpenCode's own install: not this clone
                conf.write_text(json.dumps({**cfg, "plugins": plugins}))
                self.assertEqual(ocplugin.loaded_from(), loads, plugins)
            conf.write_text(json.dumps({**cfg, "plugins": [
                {"package": str(self.copy / "opencode-plugin"), "options": {"wb": str(self.copy / "bin/wb")}}]}))
            only_git = Path(self.tmp.name) / "only-git"
            only_git.mkdir()
            (only_git / "git").symlink_to(shutil.which("git"))
            with mock.patch.dict(os.environ, {"PATH": str(only_git)}):     # no claude
                out = self.update()
        self.assertTrue((self.copy / "new.txt").exists(), out)
        self.assertIn("updated clone ", out)
        self.assertIn("OpenCode loads its plugin from this clone", out)
        self.assertFalse(self.calls.exists())                     # no claude step
        known = Path(self.tmp.name) / "elsewhere/plugins/known_marketplaces.json"   # Claude Code has it too
        known.parent.mkdir(parents=True)
        known.write_text(json.dumps({"workbench": {"installLocation": str(self.copy)}}))
        with mock.patch.object(ocplugin, "PKG_ROOT", self.copy):
            self.assertIn("already up to date", self.update())
        self.assertIn("plugin marketplace update workbench", self.calls.read_text())

    def test_a_clone_pulled_by_hand_says_its_mod_is_older_than_claude_codes_copy(self):
        # 2026-11-21: the owner's clone was current, pulled with git, and wb update --check said
        # "up to date" while Claude Code ran its cached mod from four days before: no splash
        cc = Path(self.tmp.name) / "elsewhere"
        os.environ["CLAUDE_CONFIG_DIR"] = str(cc)                       # a clone, not the marketplace's
        git = lambda *a: subprocess.run(["git", "-C", str(self.copy), *a], check=True,
                                        capture_output=True, text=True).stdout.strip()
        git("pull", "-q", "--ff-only")
        (self.copy / "mod").mkdir()
        (self.copy / "mod/register.tsx").write_text("old\n")
        git("add", "mod"); git("commit", "-qm", "mod")
        installed = git("rev-parse", "HEAD")
        (self.copy / "mod/register.tsx").write_text("new\n")
        git("commit", "-qam", "the splash")
        plugins = cc / "plugins/installed_plugins.json"
        plugins.parent.mkdir(parents=True)
        at = lambda sha: plugins.write_text(json.dumps({"version": 2, "plugins": {"workbench@workbench": [
            {"scope": "user", "installPath": "/x", "gitCommitSha": sha}]}}))
        at(installed)
        self.assertIn(f"update available: Claude Code runs the mod as of {installed[:7]}",
                      self.update("--check"))
        self.assertIn(installed[:7], self.update("--check", "--if-due"))  # no network needed
        out = self.update()                                    # the fake claude refreshes nothing
        self.assertIn(f"Claude Code still has the mod as of {installed[:7]}", out)
        (Path(self.tmp.name) / "fakebin/claude").write_text(  # this one does, as Claude Code's would
            f'#!/bin/sh\necho "$@" >> {self.calls}\n[ "$2" = update ] && [ "$3" = workbench@workbench ] && '
            f'printf %s {shlex.quote(json.dumps({"plugins": {"workbench@workbench": [{"gitCommitSha": git("rev-parse", "HEAD")}]}}))} '
            f'> {shlex.quote(str(plugins))}\nexit 0\n')
        out = self.update()
        self.assertIn(f"the mod was as of {installed[:7]}, now {git('rev-parse', '--short=7', 'HEAD')}", out)
        self.assertIn("up to date", self.update("--check"))
        (self.copy / "notes.txt").write_text("docs\n")              # news outside mod/: the mod is current
        git("add", "notes.txt"); git("commit", "-qm", "docs")
        self.assertEqual(self.update("--check").strip(), "up to date")
        at("0" * 40)                                             # a commit this clone never had
        self.assertEqual(self.update("--check").strip(), "up to date")

    def test_a_marketplace_copy_updates_through_claude_code(self):
        out = self.update()
        self.assertIn("already up to date", out)        # the fake claude pulled nothing
        self.assertEqual(self.calls.read_text().splitlines(),
                         ["plugin marketplace update workbench", "plugin update workbench@workbench"])

    def test_a_shallow_marketplace_copy_replaced_by_claude_code_reports_its_update(self):
        # a user's 0.94 to 1.4 (2026-11-20): Claude Code's clone is one commit deep and its
        # update replaces it, so counting from the old HEAD died after the update had landed
        git = lambda d, *a: subprocess.run(["git", "-C", str(d), *a], check=True, capture_output=True,
                                           text=True).stdout.strip()
        clone = ["git", "clone", "-q", "--depth", "1", f"file://{self.origin}", str(self.copy)]
        shutil.rmtree(self.copy)
        subprocess.run(clone, check=True, capture_output=True)
        old = git(self.copy, "rev-parse", "HEAD")
        (self.origin / "more.txt").write_text("y")
        git(self.origin, "add", "more.txt"); git(self.origin, "commit", "-qm", "more")
        (Path(self.tmp.name) / "fakebin" / "claude").write_text(   # its update: a new clone
            f'#!/bin/sh\necho "$@" >> {self.calls}\ncase "$*" in "plugin marketplace update"*)\n'
            f'  rm -rf {shlex.quote(str(self.copy))} && {shlex.join(clone)};; esac\n')
        out = self.update()
        self.assertIn(f"updated marketplace {old[:7]}..", out)
        self.assertNotIn("rev-list", out)
        self.assertTrue((self.copy / "more.txt").exists())
        self.assertEqual(store.read_json(store.home() / "update.json")["behind"], 0)

    def test_a_clone_ahead_of_its_upstream_or_tracking_another_remote_still_updates(self):
        # #875 (Claude's audit of 1.90.24): a clone with a local patch and nothing to pull died
        # "has commits its upstream hasn't", skipping the plugin steps; and the fetch was always
        # `origin`'s, so a clone tracking upstream/main read a stale ref, and with no origin
        # couldn't check at all
        os.environ["CLAUDE_CONFIG_DIR"] = str(Path(self.tmp.name) / "elsewhere")   # a clone
        git = lambda d, *a: subprocess.run(["git", "-C", str(d), *a], check=True,  # noqa
                                           capture_output=True)
        git(self.copy, "remote", "rename", "origin", "upstream")                 # no origin now
        self.assertIn("update available: 1 new commit(s)", self.update("--check"))
        (self.origin / "more.txt").write_text("y")
        git(self.origin, "add", "more.txt"); git(self.origin, "commit", "-qm", "more")
        self.assertIn("update available: 2 new commit(s)", self.update("--check"))
        self.assertIn("updated clone", self.update())
        self.assertTrue((self.copy / "more.txt").exists())
        self.calls.unlink()
        (self.copy / "mine.txt").write_text("x")
        git(self.copy, "add", "mine.txt"); git(self.copy, "commit", "-qm", "a local patch")
        out = self.update()
        self.assertIn("already up to date", out)
        self.assertNotIn("a fast-forward pull can't", out)
        self.assertEqual(self.calls.read_text().splitlines(),                   # the plugin refreshed
                         ["plugin marketplace update workbench", "plugin update workbench@workbench"])

    def test_a_clone_pulls_unless_it_has_changes_or_tasks_are_running(self):
        os.environ["CLAUDE_CONFIG_DIR"] = str(Path(self.tmp.name) / "elsewhere")   # not Claude Code's clone
        (self.copy / "README.md").write_text("mine")
