    def test_on_macos_the_machine_and_boot_are_read_by_absolute_path_whatever_the_path(self):
        # #1305 (bar loop round 8): the launchd agent's PATH had no /usr/sbin, so wb chat serve
        # took the host name for the machine while the mod's wb events sent the hardware UUID,
        # and a closed session's listener.json read as another machine's claim, still listening
        def run(argv, **kw):
            if argv[0] == "/usr/sbin/ioreg":
                return subprocess.CompletedProcess(argv, 0, '  "IOPlatformUUID" = "5A1B-UUID"\n', "")
            if argv[0] == "/usr/sbin/sysctl":
                return subprocess.CompletedProcess(argv, 0, "{ sec = 1732000000, usec = 1 } Wed", "")
            raise FileNotFoundError(argv[0])                 # by name: not on the agent's PATH
        real_read = Path.read_text
        def read(path, *a, **kw):
            if str(path) in ("/etc/machine-id", "/var/lib/dbus/machine-id",
                             "/proc/sys/kernel/random/boot_id"):
                raise FileNotFoundError(path)
            return real_read(path, *a, **kw)
        with mock.patch.object(store.sys, "platform", "darwin"), \
                mock.patch.object(store, "_MACHINE", []), mock.patch.object(store, "_BOOT", []), \
                mock.patch.object(Path, "read_text", read), \
                mock.patch("subprocess.run", side_effect=run), \
                mock.patch.dict(os.environ, {"PATH": "/opt/homebrew/bin:/usr/bin:/bin"}):
            self.assertEqual(store.machine(), "5A1B-UUID")       # never the host name
            self.assertEqual(store.boot_id(), "1732000000")

    def test_a_chat_on_an_address_that_comes_and_goes_rebinds_in_place_when_it_changes(self):
        # #200 (the 2026-11-19 audit): with bind ["tailscale"] the plan was loopback while the
        # tailnet was down and its address once up, but only a longer list restarted, and the
        # restart was an exit 75 that ended a chat with no service manager
        chat = self.chat
        ts = {"value": {}}
        execs = []
        with mock.patch.object(chat, "tailscale", side_effect=lambda: ts["value"]), \
                mock.patch.object(chat, "REPLAN_EVERY", 0.05), \
                mock.patch.object(chat.os, "execv", side_effect=lambda *a: (execs.append(a), sys.exit())), \
                mock.patch.object(chat, "make_servers", return_value=(
                    [types.SimpleNamespace(server_address=("127.0.0.1", 1),
                                           serve_forever=lambda: time.sleep(1),
                                           RequestHandlerClass=types.SimpleNamespace(hub=None))],
                    chat.plan(["tailscale"]))), \
                mock.patch.object(chat, "Pusher"), mock.patch.object(chat, "watch_code"):
            threading.Thread(target=chat.serve, args=(0, ["tailscale"]), kwargs={"say": lambda m: None},
                             daemon=True).start()
            time.sleep(0.3)
            self.assertEqual(execs, [])                                  # the same set: kept
            ts["value"] = {"ip": "100.64.0.9", "names": {"box"}}        # same length, other address
            deadline = time.time() + 5
            while not execs and time.time() < deadline:
                time.sleep(0.05)
        self.assertTrue(execs)                                           # re-exec'd, not exit 75

    def test_the_stream_sends_the_whole_state_then_what_changed(self):
        import http.client
        tok = self.chat.token()
        self.call("/api/send", {"text": "first"}, token=tok)
        c = http.client.HTTPConnection("127.0.0.1", self.port, timeout=10)
        c.request("GET", "/api/stream", headers={"Host": "localhost", "Authorization": f"Bearer {tok}"})
        r = c.getresponse()
        self.assertEqual(r.getheader("Content-Type"), "text/event-stream")

        def event():
            lines = []
            while True:
                line = r.fp.readline().decode().rstrip("\n")
                if not line:
                    if lines:
                        return lines
                    continue
                lines.append(line)
        first = event()
        self.assertEqual(first[0], "event: state")
        self.assertEqual([m["text"] for m in json.loads(first[1][6:])["messages"]], ["first"])
        run_wb("chat", "reply", "--text", "On it.")
        second = event()
        self.assertEqual(second[0], "event: patch")                      # only the new row (#755)
        self.assertEqual([m["text"] for m in json.loads(second[1][6:])["messages"]["put"]], ["On it."])
        c.close()
        self.assertEqual(self.call("/api/stream")[0], 401)

    def test_a_stream_ends_at_its_hubs_close_without_another_snapshot(self):
        # nightly run 45577067512 (2026-11-25): woken by tearDown's hub.close, a test's stream made
        # one more snapshot, by then in the next test's WB_HOME: the push key it cached there was
        # the key test_an_empty_or_broken_vapid_key_file_is_replaced… expected to be None
        hub = self.srv.RequestHandlerClass.hub
        page = self._held_wait("/api/stream", self.chat.token())
        got = b""
        while b"event: state" not in got:
            got += page.recv(1 << 20) or self.fail("the stream ended before its first state")
        self.addCleanup(page.close)
        made = []
        with mock.patch.object(self.chat, "snapshot", side_effect=lambda: made.append(1) or {}):
            hub.close()
            deadline = time.monotonic() + 5
            while hub.open and time.monotonic() < deadline:
                time.sleep(0.01)
        self.assertEqual(hub.open, [])                 # ended, not at its next ping's failed write
        self.assertEqual(made, [])

    def test_after_its_first_state_the_stream_sends_only_what_changed(self):
        # #755 (the 2026-11-21 audit, finding 102): every receipt and busy flip sent the whole
        # state, the thread and 20 asks with their plans: 922 KB each, five times an exchange
        import http.client
        chat, tok = self.chat, self.chat.token()
        for i in range(60):
            chat.send("x" * 1500, "user" if i % 2 else "claude")
        mine = chat.send("and the tests?", "user")
        c = http.client.HTTPConnection("127.0.0.1", self.port, timeout=10)
        c.request("GET", "/api/stream", headers={"Host": "localhost", "Authorization": f"Bearer {tok}"})
        r = c.getresponse()

        def event():
            lines = []
            while True:
                line = r.fp.readline().decode().rstrip("\n")
                if line.startswith(":"):
                    continue
                if not line:
                    if lines:
                        return lines[0][7:], json.loads(lines[1][6:]), len(lines[1])
                    continue
                lines.append(line)
        kind, first, _ = event()
        self.assertEqual((kind, len(first["messages"])), ("state", 61))       # the whole state first
        self.assertEqual(self.call("/api/ask/ask-nope", token=tok)[0], 404)  # no cards to unfold (#1350)
        chat.ack(mine["id"], "s1")                                            # a receipt
        kind, got, size = event()
        self.assertEqual(kind, "patch")
        self.assertEqual([m["id"] for m in got["messages"]["put"]], [mine["id"]])
        self.assertEqual((got["messages"]["drop"], "asks" in got), ([], False))
        self.assertLess(size, 3000)
        store.write_json(chat.chat_dir() / "listener.json",
                         {"session": "s1", "cwd": "/home/u/p", "ts": store.now(), "busy": True})
        kind, got, size = event()                                             # a busy flip
        self.assertEqual((kind, got["listener"]["busy"], "messages" in got), ("patch", True, False))
        self.assertIn("push", got)                                            # the small fields whole
        self.assertLess(size, 3000)
        store.write_json(chat.chat_dir() / "page.json", {"at": store.now()})
        line = chat.notice("Bash", "make test")                                # a waiting line comes
        kind, got, _ = event()
        self.assertEqual([m["id"] for m in got["messages"]["put"]], [line["id"]])
        chat.notice_done(line["id"])                                           # and clears (#1350)
        kind, got, _ = event()
        self.assertEqual(got["messages"]["drop"], [line["id"]])
        c.close()

    def test_a_patch_names_each_row_that_changed_or_left_and_nothing_when_nothing_did(self):
        # #755: the page merges these by id, so a row the window lost must be named
        chat, had = self.chat, {}
        snap = {"messages": [{"id": "a", "text": "1"}, {"id": "b", "text": "2"}], "listener": None, "now": 1}
        chat.patch(had, snap)
        self.assertIsNone(chat.patch(had, {**snap, "now": 2}))              # only the clock moved
        got = chat.patch(had, {**snap, "messages": [{"id": "b", "text": "2!"}, {"id": "c", "text": "3"}], "now": 3})
        self.assertEqual(got["messages"], {"put": [{"id": "b", "text": "2!"}, {"id": "c", "text": "3"}], "drop": ["a"]})
        self.assertEqual((got["now"], got["listener"]), (3, None))
        self.assertEqual(chat.patch(had, {**snap, "messages": got["messages"]["put"], "listener": {"busy": True}})
                         ["listener"], {"busy": True})

    def test_without_inotify_the_stream_stays_quiet_between_changes(self):
        # the fallback hub wakes every second; each wake was a ping (the 2026-11-16 audit)
        from workbench import watch
        saved, watch._libc = watch._libc, False
        try:
            servers, _ = self.chat.make_servers(0, ["127.0.0.1"])
        finally:
            watch._libc = saved
        srv = servers[0]
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        try:
            s = socket.create_connection(srv.server_address, timeout=10)
            s.sendall(f"GET /api/stream HTTP/1.0\r\nHost: localhost\r\n"
                      f"Authorization: Bearer {self.chat.token()}\r\n\r\n".encode())
            f = s.makefile("rb")
            while f.readline() != b"event: state\n":  # past the headers, to the first state
                pass
            f.readline(), f.readline()
            s.settimeout(3)
            self.assertEqual(f.readline(), b"\n")  # the state's own blank line, for WebKit (#1284)
            with self.assertRaises(TimeoutError):
                f.readline()  # a ping would come within a second or two
            s.close()
        finally:
            srv.shutdown()
            srv.server_close()

    def test_each_stream_event_is_followed_by_a_blank_line_of_its_own_so_webkit_hands_over_its_tail(self):
        # the #1284 review (2026-11-24): WebKit gives a streamed body to the page only up to the
        # first 8 KB of a read until more bytes come, so a state past 8 KB on a reconnect waited
        # 15 s for the ping. The blank line comes apart, NUDGE_AFTER on (stretched here to tell)
        tok = self.chat.token()
        self.chat.send("x" * 9000, "claude")                     # a state past 8 KB
        with mock.patch.object(self.chat, "NUDGE_AFTER", 0.6):
            c = self._held_wait("/api/stream", tok)
            got = b""
            while not (b"event: state" in got and got.endswith(b"\n\n")):
                got += c.recv(1 << 20)
            self.assertEqual(c.recv(1 << 20), b"\n")             # on its own, after a pause
            self.chat.reply("And a patch.")
            got = b""
            while not (b"event: patch" in got and got.endswith(b"\n\n")):
                got += c.recv(1 << 20)
            self.assertEqual(c.recv(1 << 20), b"\n")             # each event its own
            c.close()

