    def test_the_cards_ollama_may_see_come_from_its_service_alone_else_the_callers_environment(self):
        # #379 (the audit of 1.6): wb's own environment filled in what the unit left unset, which
        # a systemd service never reads
        unit = "LoadState=loaded\nActiveState=active\nEnvironment=CUDA_VISIBLE_DEVICES=1"
        hw = self.fake("Linux", runs={("systemctl",): unit})
        with mock.patch.dict(os.environ, {"CUDA_VISIBLE_DEVICES": "0", "ROCR_VISIBLE_DEVICES": "2"}):
            env, source = hw.ollama_settings()
            self.assertEqual((env["CUDA_VISIBLE_DEVICES"], source), ("1", "systemd's ollama unit"))
            self.assertNotIn("ROCR_VISIBLE_DEVICES", env)
            hw = self.fake("Linux", runs={("systemctl",): "LoadState=not-found"})
            env, source = hw.ollama_settings()       # nothing says: wb's own environment, a guess
            self.assertEqual((env["CUDA_VISIBLE_DEVICES"], env["ROCR_VISIBLE_DEVICES"], source), ("0", "2", ""))

    def test_an_ollama_container_given_some_gpus_is_budgeted_only_those(self):
        # #463 (the audit of 1.8): --gpus device=1, compose device_ids or --device
        # /dev/dri/renderD129 weren't read, so the container's Ollama was budgeted every card
        from workbench import models
        drm = "/fake/sys/class/drm"
        files = {}
        for i, slot in enumerate(("0000:03:00.0", "0000:0a:00.0")):
            for d in (f"card{i}", f"renderD{128 + i}"):
                files[f"{drm}/{d}/device/uevent"] = f"DRIVER=amdgpu\nPCI_SLOT_NAME={slot}"
            files[f"{drm}/card{i}/device/mem_info_vram_total"] = str(24 * 2 ** 30)
            files[f"{drm}/card{i}/device/mem_info_vram_vendor"] = "samsung"
        docker = lambda host: {  # noqa: E731
            ("docker", "ps"): "beef ollama/ollama:rocm llm",
            ("docker", "inspect", "--format", "{{json .Config.Env}}"): json.dumps(["OLLAMA_NUM_PARALLEL=2"]),
            ("docker", "inspect", "--format", "{{json .HostConfig}}"): json.dumps(host)}
        hw = self.fake("Linux", files=files, runs=docker(
            {"Devices": [{"PathOnHost": "/dev/kfd"}, {"PathOnHost": "/dev/dri/renderD129"}]}))
        self.assertEqual(hw.ollama_env()["ROCR_VISIBLE_DEVICES"], "1")
        self.assertEqual(hw.ollama_env()["OLLAMA_NUM_PARALLEL"], "2")
        with mock.patch.dict(os.environ, {"WB_FAKE_MODELS": "", "WB_MODELS": "/nonexistent"}):
            budget, devs, why = models.budget_devices()
        self.assertEqual(budget, 24 * 2 ** 30)
        self.assertIn("as ROCR_VISIBLE_DEVICES=1 leaves it", why)
        gpus = {"Capabilities": [["gpu"]], "Driver": ""}
        self.assertEqual(hw.container_mask({"DeviceRequests": [{**gpus, "DeviceIDs": ["1"], "Count": 0}]}),
                         {"CUDA_VISIBLE_DEVICES": "1", "CUDA_DEVICE_ORDER": "PCI_BUS_ID"})
        self.assertEqual(hw.container_mask({"DeviceRequests": [{**gpus, "Count": 2}]})["CUDA_VISIBLE_DEVICES"], "0,1")
        self.assertEqual(hw.container_mask({"DeviceRequests": [{**gpus, "Count": -1}]}), {})  # --gpus all
        self.assertEqual(hw.container_mask(["not", "a", "host config"]), {})

    def test_an_ollama_containers_own_device_mask_counts_within_the_cards_it_was_given(self):
        # #651 (Codex's audit of 1.90.6): two cards granted, CUDA_VISIBLE_DEVICES=0 in the
        # container's environment, and wb rebuilt the mask from the grants alone: both counted
        gpus = {"Capabilities": [["gpu"]], "Driver": ""}
        two = {"DeviceRequests": [{**gpus, "DeviceIDs": ["0", "1"]}]}
        from workbench import hardware
        mask = lambda host, **env: hardware.container_mask(host, env)  # noqa: E731
        self.assertEqual(mask(two, CUDA_VISIBLE_DEVICES="0"),
                         {"CUDA_VISIBLE_DEVICES": "0", "CUDA_DEVICE_ORDER": "PCI_BUS_ID"})
        remapped = {"DeviceRequests": [{**gpus, "DeviceIDs": ["2", "3"]}]}
        self.assertEqual(mask(remapped, CUDA_VISIBLE_DEVICES="1")["CUDA_VISIBLE_DEVICES"], "3")
        self.assertEqual(mask(remapped, CUDA_VISIBLE_DEVICES="1,0")["CUDA_VISIBLE_DEVICES"], "3,2")
        self.assertEqual(mask(remapped, CUDA_VISIBLE_DEVICES="0,5,1")["CUDA_VISIBLE_DEVICES"], "2")  # stops, as CUDA does
        self.assertEqual(mask(remapped, CUDA_VISIBLE_DEVICES="GPU-abc")["CUDA_VISIBLE_DEVICES"], "GPU-abc")
        self.assertEqual(mask(remapped, CUDA_VISIBLE_DEVICES="")["CUDA_VISIBLE_DEVICES"], "")  # none
        self.assertEqual(mask(remapped)["CUDA_VISIBLE_DEVICES"], "2,3")              # its own: unset
        everything = {"DeviceRequests": [{**gpus, "Count": -1}]}                     # --gpus all
        self.assertEqual(mask(everything, CUDA_VISIBLE_DEVICES="1", CUDA_DEVICE_ORDER="PCI_BUS_ID"),
                         {"CUDA_VISIBLE_DEVICES": "1", "CUDA_DEVICE_ORDER": "PCI_BUS_ID"})
        self.assertEqual(mask(everything, CUDA_VISIBLE_DEVICES="1"), {"CUDA_VISIBLE_DEVICES": "1"})
        self.assertEqual(mask(everything), {})
        hw = self.fake("Linux", runs={
            ("docker", "ps"): "beef ollama/ollama llm",
            ("docker", "inspect", "--format", "{{json .Config.Env}}"): json.dumps(
                ["OLLAMA_NUM_PARALLEL=2", "CUDA_VISIBLE_DEVICES=0"]),
            ("docker", "inspect", "--format", "{{json .HostConfig}}"): json.dumps(remapped)})
        self.assertEqual(hw.ollama_env()["CUDA_VISIBLE_DEVICES"], "2")

    def test_an_ollama_containers_readable_process_still_gets_the_cards_its_container_was_given(self):
        # the review of #463: rootless docker's processes are this user's, so /proc read first
        # found the container's ollama serve, which gives its knobs only, and its HostConfig's
        # --gpus device=1 was never asked: every card was budgeted
        hw = self.fake("Linux", runs={
            ("docker", "ps"): "beef ollama/ollama llm",
            ("docker", "inspect", "--format", "{{json .Config.Env}}"): json.dumps(["OLLAMA_NUM_PARALLEL=2"]),
            ("docker", "inspect", "--format", "{{json .HostConfig}}"): json.dumps(
                {"DeviceRequests": [{"Driver": "", "Capabilities": [["gpu"]], "DeviceIDs": ["1"]}]})})
        with tempfile.TemporaryDirectory() as d:
            Path(d, "300", "ns").mkdir(parents=True)
            Path(d, "300", "comm").write_text("ollama\n")
            Path(d, "300", "cmdline").write_bytes(b"/bin/ollama\0serve\0")
            Path(d, "300", "environ").write_bytes(b"OLLAMA_NUM_PARALLEL=2\0CUDA_VISIBLE_DEVICES=0\0")
            os.symlink("mnt:[2]", Path(d, "300", "ns", "mnt"))   # another mount namespace
            Path(d, "self", "ns").mkdir(parents=True)
            os.symlink("mnt:[1]", Path(d, "self", "ns", "mnt"))
            with mock.patch("workbench.hardware.PROC", Path(d)):
                env, source = hw.ollama_settings()
        self.assertEqual((env["CUDA_VISIBLE_DEVICES"], env["OLLAMA_NUM_PARALLEL"], source),
                         ("1", "2", "the docker container llm"))

    def test_ollamas_settings_come_from_the_ollama_that_runs_a_process_or_a_container(self):
        # #379 (the audit of 1.6): an ollama serve started by hand, or one in Docker, had its
        # OLLAMA_NUM_PARALLEL and OLLAMA_MAX_LOADED_MODELS read from systemd or wb's environment
        from workbench import models
        unit = "LoadState=loaded\nActiveState=inactive\nEnvironment=OLLAMA_NUM_PARALLEL=1"
        docker = {("docker", "ps"): "f00d ghcr.io/x/open-webui:main webui\nbeef ollama/ollama:rocm llm",
                  ("docker", "inspect"): json.dumps(["OLLAMA_NUM_PARALLEL=3", "OLLAMA_HOST=0.0.0.0:11434",
                                                     "OLLAMA_MODELS=/root/.ollama", "PATH=/usr/bin"])}
        hw = self.fake("Linux", runs={("systemctl",): unit, **docker})
        env, source = hw.ollama_settings()   # a container: its knobs, not its paths or its bind
        self.assertEqual((env["OLLAMA_NUM_PARALLEL"], env["OLLAMA_HOST"], env["OLLAMA_MODELS"], source),
                         ("3", "", "", "the docker container llm"))
        hw = self.fake("Linux", runs={("systemctl",): unit})
        self.assertEqual(hw.ollama_settings()[1], "systemd's ollama unit, not running")
        with tempfile.TemporaryDirectory() as d:
            proc = Path(d)

            def process(pid, argv, environ, ns="mnt:[1]"):
                Path(proc, pid, "ns").mkdir(parents=True)
                Path(proc, pid, "comm").write_text("ollama\n")
                Path(proc, pid, "cmdline").write_bytes(b"\0".join(argv) + b"\0")
                Path(proc, pid, "environ").write_bytes(b"\0".join(environ) + b"\0")
                os.symlink(ns, Path(proc, pid, "ns", "mnt"))
            Path(proc, "self", "ns").mkdir(parents=True)
            os.symlink("mnt:[1]", Path(proc, "self", "ns", "mnt"))
            process("90", [b"/usr/bin/ollama", b"runner"], [b"OLLAMA_NUM_PARALLEL=9"])  # not the server
            process("120", [b"/usr/bin/ollama", b"serve"],
                    [b"OLLAMA_NUM_PARALLEL=4", b"CUDA_VISIBLE_DEVICES=1", b"OLLAMA_HOST=127.0.0.1:11500", b"HOME=/x"])
            with mock.patch("workbench.hardware.PROC", proc):
                env, source = hw.ollama_settings()   # started by hand: ahead of any unit
                self.assertEqual((env["OLLAMA_NUM_PARALLEL"], env["CUDA_VISIBLE_DEVICES"],
                                  env["OLLAMA_HOST"], source),
                                 ("4", "1", "127.0.0.1:11500", "the running ollama's environment (pid 120)"))
                self.assertNotIn("HOME", env)
                os.unlink(Path(proc, "120", "ns", "mnt"))
                os.symlink("mnt:[2]", Path(proc, "120", "ns", "mnt"))  # a container's, seen from here
                env, source = hw.ollama_settings()
                self.assertEqual((env["OLLAMA_NUM_PARALLEL"], env["OLLAMA_HOST"]), ("4", ""))
                self.assertNotIn("CUDA_VISIBLE_DEVICES", env)
                self.assertIn("in a container: its knobs only", source)
                if os.geteuid():  # another user's ollama (a system unit's): systemd says instead
                    Path(proc, "120", "environ").chmod(0)
                    self.assertEqual(hw.ollama_settings()[1], "systemd's ollama unit, not running")
        ollama = models.Model(id="o/m", provider="o", name="m", base_url="http://127.0.0.1:11434/v1",
                              engine="ollama", label="o/m")
        hw = self.fake("Linux")
        with mock.patch.object(models, "_fake", lambda: False), \
                mock.patch.object(models, "discover", lambda: {"o/m": ollama}):
            self.assertIn("ollama's settings unknown", cli.ollama_line())   # wb doctor, wb scout
            self.assertIn("gpu_gb sets the GPU budget and each model's vram_gb its size", cli.ollama_line())
            hw = self.fake("Linux", runs={("systemctl",): unit})
            self.assertEqual(cli.ollama_line(),
                             "ollama's settings: from systemd's ollama unit, not running (OLLAMA_NUM_PARALLEL=1)")

