    def test_a_loaded_skill_shows_where_its_files_are(self):
        lib = Path(os.environ["WB_SKILLS"])
        d = write_skill(lib / "deep", "deep", "Use when CANARY-DEEP.",
                        "Read references/api.md for the table.\n")
