    def test_a_roles_thinking_review_is_off_by_default_and_goes_on_on_api_only_on_the_dialogs_yes(self):
        # #1059 (2026-11-25): the self-review thinking is one more paid round on API, so it takes
        # the user's yes as thinking does; every view says "thinking: review only"
        self.assertEqual(self.route("trivial", "deepseek/deepseek-flash", "--day-usd", "5")[0], 0)
        self.assertNotIn("thinking_review", self.doc()["roles"]["trivial"])        # off by default
        os.environ["CLAUDECODE"] = "1"
        asked = self.dry("trivial", "--thinking-review", "on")
        self.assertEqual((asked["change"], asked["gate"]), (
            "trivial: self-review thinking off → on (thinking: review only: the agent reviews its own change in "
            "one more round before Claude)", True))
        self.assertEqual(asked["approval"]["argv"], ["route", "trivial", "--thinking-review", "on"])
        self.assertEqual(self.route("trivial", "--thinking-review", "on")[0], 3)    # no yes: unchanged
        self.assertNotIn("thinking_review", self.doc()["roles"]["trivial"])
        self.approve(asked["approval"])
        self.assertEqual(self.route("trivial", "--thinking-review", "on")[0], 0)
        self.assertFalse(self.dry("significant", "--thinking-review", "on")["gate"])  # a GPU role with no API model
        os.environ.pop("CLAUDECODE")
        self.assertEqual(self.doc()["roles"]["trivial"]["thinking_review"], "on")
        self.assertIn("trivial      API deepseek/deepseek-flash (DeepSeek) · thinking: review only · ", self.route()[1])
        self.assertEqual(routes.summary(routes.read()), "significant GPU (the router picks); trivial API "
                         "deepseek/deepseek-flash, thinking: review only; writing GPU (the router picks)")
        # with the role's thinking on every round thinks: said as thinking on, as before
        self.assertEqual(routes.thinking_said({**routes.read()["roles"]["trivial"], "thinking": "on"}), "thinking on")
        from workbench import settings  # the web app's thinking row says the coding rounds' alone
        self.assertEqual(settings._think_stops(routes.read()["roles"]["trivial"])[0], settings.THINK[0])
        self.assertEqual(self.route("trivial", "--thinking-review", "off")[0], 0)
        self.assertNotIn("thinking_review", self.doc()["roles"]["trivial"])
        self.path.write_text(json.dumps({"v": 1, "roles": {"trivial": {"thinking_review": "yes"}}}))
        with self.assertRaisesRegex(routes.RoutesError, "trivial's thinking_review is 'yes', not off or on"):
            routes.read()

    def test_wb_settings_set_dry_runs_each_route_row_as_that_rows_own_wb_route_dry_run(self):
        # #1336 (#1296's G3): Claude's wb settings set on a row wb route gates reaches the mod's
        # dialog, which shows what `wb settings set … --dry-run --json` prints. It must be that
        # row's wb route dry run word for word, or the user approves a line the change isn't; only
        # a role's selector was tested (#1287)
        from workbench import settings

        def settings_set(*argv):
            out, err, code = io.StringIO(), io.StringIO(), 0
            with redirect_stdout(out), redirect_stderr(err):
                try:
                    cli.main(["settings", "set", *argv])
                except SystemExit as e:
                    code = e.code
            return code, out.getvalue(), err.getvalue()

        self.route("trivial", "deepseek/deepseek-flash", "--day-usd", "5")
        runner.models.hosted(fresh=True)
        settings.drop()
        self.addCleanup(settings.drop)
        os.environ["CLAUDECODE"] = "1"
        for key, value, gate in (("role-trivial", "gpu", True), ("cap", "9", True), ("think-trivial", "on", True),
                                 ("api-writing", "anthropic/claude-haiku-5-5", True),
                                 ("gpu-significant", "auto", False)):
            with self.subTest(key=key):
                code, out, err = settings_set("--dry-run", "--json", key, value)
                argv = settings._argv(settings._row(key), value)
                self.assertEqual((code, argv[0]), (0, "route"), err)
                self.assertEqual(json.loads(out), self.dry(*argv[1:]))
                self.assertEqual(json.loads(out)["gate"], gate)
        self.assertFalse(self.ok.exists())
        self.assertEqual(self.doc()["day_usd"], 5)                # a dry run writes nothing
        # a change wb route refuses is refused by the dry run too (exit 3, wb's line): no dialog
        code, out, err = settings_set("--dry-run", "--json", "api-writing", "nosuch/a-model")
        self.assertEqual((code, out), (3, ""))
        self.assertIn(cli.ROUTE_CATALOG, err)
        # the dialog's Allow: the dry run's approval is the one the real call takes, once
        q = json.loads(settings_set("--dry-run", "--json", "cap", "9")[1])
        self.assertEqual(settings_set("cap", "9")[0], 3)          # no yes yet: not changed
        self.approve(q["approval"])
        code, out, err = settings_set("cap", "9")
        self.assertEqual((code, out), (0, f"changed: {q['change']}\n"), err)
        self.assertEqual(self.doc()["day_usd"], 9)
        self.assertFalse(self.ok.exists())

    def test_thinking_on_a_gpu_role_that_runs_on_its_api_model_under_agents_api_or_busy_needs_the_dialog(self):
        # #1149 (2026-11-24): the gate read the role's own via, so with Agents on API (or the busy
        # opt-in on) a thinking change came with no dialog, and every API start of the role then
        # billed reasoning tokens the user never approved
        for setup in ({"use": "api"}, {"busy": "api"}):
            with self.subTest(setup=setup):
                self.path.write_text(json.dumps({"v": 1, "day_usd": 5, **setup, "roles": {"trivial": {
                    "via": "gpu", "api": "deepseek/deepseek-flash", "thinking": "off"}}}))
                doc = routes.read()
                self.assertTrue(routes.change(doc, "trivial", thinking="on").gated)
                self.assertTrue(routes.change(doc, "all", thinking="on").gated)
                self.assertFalse(routes.change(doc, "significant", thinking="on").gated)  # no API model
                os.environ["CLAUDECODE"] = "1"
                asked = self.dry("trivial", "--thinking", "on")
                self.assertEqual((asked["change"], asked["gate"]), ("trivial: thinking off → on", True))
                was = self.path.read_text()
                code, out, err = self.route("trivial", "--thinking", "on")
                self.assertEqual((code, out), (3, ""))
                self.assertIn("in Claude Code a role changes only through the workbench mod's dialog", err)
                self.assertEqual(self.path.read_text(), was)
                os.environ.pop("CLAUDECODE")
        # Agents on API: the role already runs there, so a new API model is the next start's
        self.path.write_text(json.dumps({"v": 1, "day_usd": 5, "use": "api", "roles": {"trivial": {
            "via": "gpu", "api": "deepseek/deepseek-flash"}}}))
        self.assertEqual(self.dry("trivial", "--api", "anthropic/claude-haiku-5-5")["change"],
                         "trivial: API model deepseek/deepseek-flash → anthropic/claude-haiku-5-5 (Anthropic), "
                         "used from the next start")

    def test_under_agents_api_a_roles_new_api_model_is_said_as_the_next_starts_and_only_its_move_as_held(self):
        # #1236 (2026-11-24): `wb route trivial <id>`, the form the skill prescribes, said the
        # whole change waited for Agents on Both, but the role's next start ran on the new model
        held = "Agents is API, so the move of trivial to API applies once Agents is Both (wb route all both)"
        self.path.write_text(json.dumps({"v": 1, "day_usd": 5, "use": "api", "roles": {r: {
            "via": "gpu", "api": "deepseek/deepseek-flash"} for r in routes.ROLES}}))
        asked = self.dry("trivial", "deepseek/deepseek-v4-pro")
        self.assertEqual((asked["change"], asked["gate"]), (
            "trivial: API model deepseek/deepseek-flash → deepseek/deepseek-v4-pro (DeepSeek), used from the "
            f"next start · GPU → API deepseek/deepseek-v4-pro; {held}", True))
        self.assertEqual(self.route("trivial", "deepseek/deepseek-v4-pro")[0], 0)
        m, _, _, routed = routes.resolve("trivial", "trivial", None)
        self.assertEqual((m.id, routed["via"]), ("deepseek/deepseek-v4-pro", "api"))   # as the line said
        # the same model, moved: nothing changes until Both
        self.assertEqual(self.dry("significant", "api")["change"],
                         "significant: GPU → API deepseek/deepseek-flash; Agents is API, so the move of significant "
                         "to API applies once Agents is Both (wb route all both)")
        # a role already on API given a new model: all of it now, nothing held
        self.assertEqual(self.dry("trivial", "deepseek/deepseek-flash")["change"],
                         "trivial: API deepseek/deepseek-v4-pro → API deepseek/deepseek-flash · your code goes to "
                         "DeepSeek · thinking off · cap $5/day")
        # several roles in one change: the same, the moves named
        self.assertEqual(routes.change_pairs(routes.read(), [("significant", "api", "deepseek/deepseek-v4-pro"),
                                                             ("trivial", "gpu", None)]).line,
                         "significant: API model deepseek/deepseek-flash → deepseek/deepseek-v4-pro (deepseek), used "
                         "from the next start · GPU → API deepseek/deepseek-v4-pro · trivial: API "
                         "deepseek/deepseek-v4-pro → GPU · your code goes to deepseek · thinking off · cap $5/day · "
                         "Agents is API, so the moves of significant to API, trivial to the GPU apply once Agents is "
                         "Both (wb route all both)")

    def test_under_agents_api_a_roles_held_move_still_says_what_its_model_does_with_thinking(self):
        # #1236 and #1237 met in the bar4 merge (2026-11-24): #1236's held move restates the
        # role's clauses through a second _role_part, which dropped #1237's `thinks`, so under
        # Agents API the thinking clause said the role's setting again, not what the model does
        doc = {"v": 1, "day_usd": 5, "use": "api", "roles": {r: {
            "via": "gpu", "gpu": None, "api": "deepseek/deepseek-flash", "thinking": "off"} for r in routes.ROLES}}
        line = routes.change(doc, "significant", via="api", thinking="on",
                             thinks=lambda mid, t: f"{mid} thinks {t}").line
        self.assertIn("thinking off → on: deepseek/deepseek-flash thinks on", line)
        self.assertIn("the move of significant to API applies once Agents is Both", line)

    def test_thinking_turned_on_while_a_roles_api_side_is_dormant_is_named_by_the_yes_that_sends_it_there(self):
        # #1177 (2026-11-24): thinking on a GPU role (an API model kept, or none yet) needs no
        # dialog, but the later yes to Agents API, busy api or a new API model never said it, so
        # every API task of the role ran on the reasoning variant nobody agreed to
        self.route("trivial", "deepseek/deepseek-flash", "--day-usd", "5")
        self.route("trivial", "gpu")
        os.environ["CLAUDECODE"] = "1"
        self.assertEqual(self.route("trivial", "--thinking", "on")[:2],
                         (0, "changed: trivial: thinking off → on\n"))
        for argv in (("all", "api"), ("busy", "api")):
            with self.subTest(argv=argv):
                asked = self.dry(*argv)
                self.assertTrue(asked["gate"])
                self.assertIn("thinking on (trivial)", asked["change"])
        self.assertNotIn("thinking", self.dry("all", "gpu")["change"])   # nothing newly on API
        self.approve(self.dry("all", "api")["approval"])
        code, out, err = self.route("all", "api")
        self.assertEqual(code, 0, err)
        self.assertIn("thinking on (trivial)", self.doc()["roles"]["trivial"]["said"])
        # no API model yet: under Agents API, and under the busy opt-in, the --api line names it
        for setup in ({"use": "api"}, {"busy": "api"}):
            with self.subTest(setup=setup):
                self.path.write_text(json.dumps({"v": 1, "day_usd": 5, **setup, "roles": {
                    "writing": {"via": "gpu", "thinking": "off"}}}))
                self.assertEqual(self.route("writing", "--thinking", "on")[0], 0)
                asked = self.dry("writing", "--api", "anthropic/claude-haiku-5-5")
                self.assertTrue(asked["gate"])
                self.assertIn("thinking on", asked["change"])
        self.assertIn("when the GPU is busy, writing starts on its API model (your code goes to Anthropic "
                      "(writing); thinking on (effort high) (writing); cap $5/day)", asked["change"])  # #1237: its effort

