        spec = store.Task("t-x").spec
        self.assertEqual((spec["session"], spec["claude_pid"], "driver" in spec), ("sess-2", b.pid, False))
        self.assertEqual(self.wb("adopt", "t-x", "--pid", str(b.pid))[0], 2)  # its ids, as before 2.2

