    def test_a_providers_stop_is_not_held_against_the_steps_size(self):
        from workbench import models, results, router
        os.environ.update(FAKE_RETRIES="200", FAKE_RETRY_EVERY="0.5")
        task = self.api_task("t-size", "ratelimit", "--silence-timeout", "2")
        with mock.patch.object(runner, "RATE_WAIT_S", 2), mock.patch.object(models, "RATE_LIMIT_SECS", 1):
            runner.drive(task)
        self.assertEqual(task.status["phase"], "stuck")
        for i in range(3):                                          # what the agent wrote first
            (task.worktree / f"part{i}.py").write_text("x = 1\n")
        self.assertIs(results.step(task, False)["stuck"], False)
        m = models.resolve(task.spec["model"])
        before = router.slice(m)
        run_wb("discard", "t-size")
        # the fake's model is a GPU entry run as an API task (task.json `via`): its row says `kind`
        # api, and #1022's slice reads only rows of the model's own kind, so the row is given the
        # entry's kind here, or neither check below would read it (the wave 2 merge)
        rows, _ = store.read_jsonl(store.home() / "results.jsonl")
        (store.home() / "results.jsonl").write_text(
            "".join(json.dumps(r) + "\n" for r in [*rows[:-1], {**rows[-1], "kind": m.kind}]))
        row = store.results()[-1]
        self.assertIs(row["steps"][-1]["stuck"], False)
        self.assertEqual((router.slice(m).files, router.slice(m).lines), (before.files, before.lines))
        # the same stop as the step's own (cause "guard"): stuck, and the slice shrinks; the row's
        # `infra` (the provider's stop) stays out, or stopped_outside leaves the copy unjudged (#1245)
        store.append_jsonl(store.home() / "results.jsonl",
                           {**{k: v for k, v in row.items() if k != "infra"}, "ts": time.time(),
                            "steps": [{**row["steps"][-1], "stuck": True}]})
        self.assertLess(router.slice(m).files, before.files)

    def test_the_carry_on_after_a_providers_stop_is_not_counted_as_a_review_round(self):
        # the stop notice's own advice, wb feedback "carry on", counted as a review the agent
        # caused: with one real review the step read as two, went badly and shrank the model's
        # slice (#1153, 2026-11-24)
        from workbench import results, router, tuning
        os.environ.update(FAKE_RETRIES="200", FAKE_RETRY_EVERY="0.5")
        task = self.api_task("t-carry", "ratelimit", "--silence-timeout", "2")
        with mock.patch.object(runner, "RATE_WAIT_S", 2):
            runner.drive(task)
        self.assertEqual((task.status["phase"], task.status.get("infra"), task.status.get("reviews", 0)),
                         ("stuck", "provider", 0))
        routes = Path(self.tmp.name) / "routes.json"   # wb feedback on an API task needs a cap (#1089)
        routes.write_text(json.dumps({"v": 1, "day_usd": 5, "roles": {}}))
        os.environ["WB_ROUTES"] = str(routes)
        os.environ["FAKE_SCENARIO"] = "ok"
        with mock.patch.object(cli, "spawn_runner"):
            out = run_wb("feedback", "t-carry", "--text", "carry on")
        self.assertIn("no review round is counted", out)
        self.assertEqual((task.status["reviews"], task.status["round_for"]), (0, "resume"))
        runner.drive(task)
        self.assertEqual(task.status["phase"], "review", task.status.get("last"))
        step = results.step(task, True)
        self.assertEqual((step["reviews"], tuning.agent_reviews(step)), (0, 0))
        # one real review after it is one, and the step still went well
        with mock.patch.object(cli, "spawn_runner"):
            self.assertIn("feedback round 1 sent", run_wb("feedback", "t-carry", "--text", "rename x"))
        runner.drive(task)
        step = results.step(task, True)
        self.assertEqual(tuning.agent_reviews(step), 1)
        self.assertEqual(router._went(step), "well")

    def test_keep_alives_before_the_first_token_are_the_providers_queue_not_thinking(self):
        # DeepSeek holds a request open with keep-alives up to 10 minutes before inference starts
        task = self.api_task("t-queue", "api", "--think-timeout", "2", "--silence-timeout", "30")
        self.up.keepalive = 8
        self.keyhole(task)
        with mock.patch.object(self.kh_mod, "QUEUED_AFTER_S", 1):
            runner.drive(task)
        st = task.status
        self.assertEqual((st["phase"], st.get("nudges", 0)), ("review", 0), st.get("last"))
        [ev] = self.events(task, "rate_limited")
        self.assertEqual(ev["state"], "queued")
        other = self.api_task("t-queue2", "api", "--think-timeout", "2", "--silence-timeout", "30")
        self.keyhole(other)
        with mock.patch.object(self.kh_mod, "QUEUED_AFTER_S", 3600):  # without the mark
            runner.drive(other)
        self.assertGreaterEqual(other.status.get("nudges", 0), 1)

    def test_a_provider_queue_that_never_answers_stops_as_its_outage_not_the_agents_failure(self):
        # #1083: DeepSeek holds a request with keep-alives and closes it unstarted; the queue
        # paused every clock, OpenCode resent it ten times (~110 minutes), then the round failed
        # as the agent's (cause agent, against its slice). Now a queue OpenCode gives up on, or one
        # held QUEUE_WAIT_S, is an `outage`: revived once, then stuck as the provider's
        from workbench import results
        os.environ["FAKE_CUT_RETRIES"] = "2"
        self.up.unanswered = True
        cases = [("t-qgone", None, r"^deepseek held the agent's requests in its queue for \d+ seconds without answering$"),
                 ("t-qlong", 3, r"^deepseek held the agent's requests in its queue for \d+ seconds without answering$"),
                 ("t-cut", None, r"^deepseek cut its answers short \(OpenAI Chat stream ended without finish_reason\)$")]
        for name, bound, want in cases:
            with self.subTest(name=name):
                self.up.keepalive = 30 if bound else 0 if name == "t-cut" else 1.6
                task = self.api_task(name, "api", "--think-timeout", "2", "--silence-timeout", "60")
                self.keyhole(task, hold=60)
                began = time.monotonic()
                with mock.patch.object(self.kh_mod, "QUEUED_AFTER_S", 1), \
                        mock.patch.object(runner, "RATE_WAIT_S", 1), \
                        mock.patch.object(runner, "QUEUE_WAIT_S", bound or runner.QUEUE_WAIT_S):
                    runner.drive(task)
                st = task.status
                self.assertEqual((st["phase"], st.get("infra")), ("stuck", "provider"), st.get("last"))
                self.assertRegex(st["last"], want)
                self.assertEqual(len(self.events(task, "load")), 1)     # revived once
                n = self.notice(task)
                self.assertEqual((n["kind"], n["cause"]), ("stuck", "provider"))
                self.assertFalse(results.step(task, landed=False)["stuck"])
                if name != "t-cut":
                    self.assertIn("queued", [e["state"] for e in self.events(task, "rate_limited")])
                if bound:
                    self.assertLess(time.monotonic() - began, 30)        # never the 30 s queue
        # OpenCode 2.3.2 types the model's own overrun provider.invalid-output too, with no status
        # and no queue: that stays the step's, never a provider `outage` (the review of #1083)
        wait = runner._ProviderWait(store.Task("t-cut"), 2)
        wait.on_error({"error": {"type": "provider.invalid-output",
                                 "message": "The model exceeded its output limit"}})
        self.assertIsNone(wait.stop(time.time(), gave_up=True))

    def test_a_402_stops_the_round_at_once_with_the_remedy_and_no_revive(self):
        task = self.api_task("t-402", "api", "--silence-timeout", "30")
        self.up.rate_until, self.up.code, self.up.after = float("inf"), 402, None
        self.up.body = "Insufficient balance"
        self.keyhole(task)
        runner.drive(task)
        st = task.status
        self.assertEqual((st["phase"], st["last"], st.get("infra")),
                         ("stuck", "deepseek says the account is out of credit (HTTP 402)", "provider"))
        self.assertEqual(len(self.up.seen), 1)                      # no retry loop, ours or OpenCode's
        self.assertIsNone(st.get("api_stop"))                       # consumed by the stop
        self.assertTrue([e for e in self.events(task, "error") if "keyhole: deepseek says the account "
                         "is out of credit (HTTP 402): the round stops" in e["text"]])  # a 400: no retry
        self.assertFalse(self.events(task, "load"))                 # never revived
        n = self.notice(task)
        self.assertEqual(n["cause"], "provider")
        self.assertIn("top up your deepseek account, or wait for the plan's reset", n["text"])
        self.assertEqual(self.models.api_health("deepseek")["state"], "no_credit")
        # OpenCode's own provider.quota (no keyhole between): the same stop. The credit comes
        # back first: with t-402's told stop still standing, t-402b would wait behind it as
        # queued with no stop of its own (#1344), and this test hung in CI (2026-11-24)
        self.models.note_api("deepseek", "ok")
        fake = self.api_task("t-402b", "quota", "--silence-timeout", "30")
        runner.drive(fake)
        self.assertEqual((fake.status["phase"], self.notice(fake)["cause"]), ("stuck", "provider"))
        self.assertIn("(HTTP 402)", fake.status["last"])

    def test_anthropics_400_credit_balance_too_low_stops_the_round_as_a_spent_balance(self):
        # #1079 (2026-11-23): Anthropic answers a spent balance with 400 invalid_request_error,
        # read as no quota: the task failed as the agent's, with no remedy and no no_credit mark
        low = ("Your credit balance is too low to access the Anthropic API. Please go to Plans & "
               "Billing to upgrade or purchase credits.")
        task = self.api_task("t-400c", "api", "--silence-timeout", "30")
        self.up.rate_until, self.up.code, self.up.after = float("inf"), 400, None
        self.up.body = low
        self.keyhole(task)
        runner.drive(task)
        st = task.status
        self.assertEqual((st["phase"], st["last"], st.get("infra")),
                         ("stuck", "deepseek says the account is out of credit (HTTP 400)", "provider"))
        self.assertEqual(len(self.up.seen), 1)
        n = self.notice(task)
        self.assertEqual(n["cause"], "provider")
        self.assertIn("top up your deepseek account, or wait for the plan's reset", n["text"])
        self.assertEqual(self.models.api_health("deepseek")["state"], "no_credit")
        # OpenCode's own error line, no keyhole between: the same stop; another 400 isn't one, but
        # the request the provider refused it is (#1082), with no top-up remedy
        wait = runner._ProviderWait(task, 1)
        wait.on_error({"error": {"type": "provider.invalid-request", "status": 400, "message": low}})
        self.assertEqual(wait.fatal[0], "quota")
        wait = runner._ProviderWait(task, 1)
        wait.on_error({"error": {"type": "provider.invalid-request", "status": 400,
                                 "message": "max_tokens: billing tier allows at most 8192"}})
        self.assertEqual(wait.fatal, ("refused", "deepseek refused the request (HTTP 400): "
                                                 "max_tokens: billing tier allows at most 8192"))

