    def test_the_keyholes_usage_books_each_response_and_opencodes_figure_only_adds_what_it_lacks(self):
        task = self.api_task("t-kh-meter", SPEND_M)
        mt = self.meter.for_task(task, runner.models.lookup(SPEND_M))  # as drive makes it
        mt.begin(1)
        mt.on_usage({"prompt_tokens": 1100, "completion_tokens": 40,  # Chat Completions, a cache hit
                     "prompt_tokens_details": {"cached_tokens": 1000},
                     "completion_tokens_details": {"reasoning_tokens": 10}})
        mt.on_usage({"input_tokens": 10, "output_tokens": 5, "cache_read_input_tokens": 2000,
                     "cache_creation_input_tokens": 0})                  # Anthropic's
        mt.on_usage({"input_tokens": 300, "output_tokens": 9, "cost": 0.0123})  # the provider's own
        a, b, c = self.rows("t-kh-meter", "step")
        self.assertEqual((a["tok"], a["usd"], a["source"]),
                         ({"in": 100, "cache_read": 1000, "cache_write": 0, "out": 30, "reasoning": 10},
                          (100 * 5000 + 1000 * 50) / 1e6, "keyhole"))
        self.assertEqual(b["tok"]["cache_read"], 2000)
        self.assertEqual((c["usd"], c["source"]), (0.0123, "provider"))
        mt.step({"cost": 0.1, "tokens": {"input": 100}})       # OpenCode's says less: nothing booked
        self.assertEqual(len(self.rows("t-kh-meter")), 3)
        mt.step({"cost": 3.0, "tokens": {"input": 100}})       # more than all three: the difference,
        (rec,) = self.rows("t-kh-meter", "reconcile")          # a usage.cost row as booked: OpenCode
        # reports that same figure (#1234, 2026-11-24); an estimated_cost one at its catalog's (#1165)
        self.assertAlmostEqual(rec["usd"], 3.1 - (a["usd"] + b["usd"] + c["usd"]), places=9)
        mt.step({"cost": 0.5, "tokens": {"input": 100}})       # after a reconcile: only its own
        self.assertEqual([round(r["usd"], 9) for r in self.rows("t-kh-meter", "reconcile")][1:], [0.5])
        self.assertEqual(self.meter.usage_tokens({"input_tokens": 50, "output_tokens": 20,  # Responses
                                                  "input_tokens_details": {"cached_tokens": 30},
                                                  "output_tokens_details": {"reasoning_tokens": 5}}),
                         {"in": 20, "cache_read": 30, "cache_write": 0, "out": 15, "reasoning": 5})

    def test_costs_are_catalog_estimates_until_the_user_sets_the_models_prices_and_clear_brings_the_estimate_back(self):
        # #1135 (2026-11-23): the catalog priced DeepInfra's flash model at 0.2/0.6 where DeepInfra
        # billed 0.098/0.294, so every figure ran 2x high and said nothing of being an estimate
        from workbench import models, results, savings
        a_million = {"prompt_tokens": 1_000_000, "completion_tokens": 1_000_000}

        def task_at(name, info_cost):
            """A task's response metered by the keyhole, then its round's export at OpenCode's
            figure (``info_cost``): its ledger row, its results row's line and its round report's."""
            task = self.api_task(name, SPEND_FLASH)
            m = models.lookup(SPEND_FLASH)
            mt = self.meter.for_task(task, m)
            mt.begin(1)
            mt.on_usage(a_million)
            mt.end_round({"s1": {"info": {"cost": info_cost}}})
            (row,) = self.rows(name)                      # OpenCode agrees: no reconcile row
            line = savings.paid({"kind": "api", "provider": "meterco", "model": SPEND_FLASH,
                                 "api": results.api_usage(task)})
            return m, row, line, runner._spend_part(task)

        out = run_wb("model", "price", SPEND_FLASH, "--input", "0.098", "--output", "0.294", "--cache-read", "0.00294")
        self.assertIn("your prices, $0.098 in / $0.294 out / $0.00294 cache read / $0 cache write per 1M "
                      "tokens (cache write at the catalog's ratio to input: --cache-write to set)", out)
        m, row, line, report = task_at("t-mine", 0.392)
        self.assertEqual((round(row["usd"], 9), row.get("prices")), (0.392, "yours"))
        self.assertEqual(line, "paid $0.39")                # the user's prices: no ≈, no note (#1322)
        self.assertEqual(report, " · $0.39 so far")
        self.assertEqual(self.meter.tail(m), " · today $0.39 of $100.00")
        self.assertIn("$0.098/$0.294 per 1M in/out", run_wb("models", "--api", "flash"))
        runner.CURRENT["keyhole"] = types.SimpleNamespace(task=store.Task("t-mine"), model=m)
        catalog = json.loads(runner.write_catalog(store.Task("t-mine")).read_text())  # OPENCODE_MODELS_PATH's
        self.assertEqual(catalog["meterco"]["models"]["flash-1"]["cost"]["text"],
                         {"input": {"price": 0.098, "cache": {"read": 0.00294, "write": 0.0}},
                          "output": {"price": 0.294}})

        self.assertIn("back to the catalog's prices", run_wb("model", "price", SPEND_FLASH, "--clear"))
        m, row, line, report = task_at("t-est", 0.8)
        self.assertEqual((round(row["usd"], 9), row.get("prices")), (0.8, None))
        self.assertEqual(line, "paid ≈$0.80")
        self.assertEqual(report, " · ≈$0.80 so far")
        self.assertEqual(self.meter.tail(m), " · today ≈$1.19 of $100.00")  # one estimate in it
        self.assertIn("$0.2/$0.6 per 1M in/out", run_wb("models", "--api", "flash"))
        week = savings.api_totals([{"kind": "api", "provider": "meterco", "ts": time.time(),
                                    "api": results.api_usage(store.Task(n))} for n in ("t-mine", "t-est")])
        self.assertEqual(savings.api_summary(week), "api: 2 task(s) · ≈$1.19 (meterco ≈$1.19)")
        self.assertIn("by day: ", savings.api_report(week, "week", None, savings.spent()))
        self.assertIn("≈$1.19 (≈$1.19 today)", savings.api_report(week, "week", None, savings.spent()))

    def test_prices_set_with_only_input_and_output_meter_cache_reads_at_the_catalogs_ratio_to_input(self):
        # #1155 (2026-11-24): `wb model price <id> --input X --output Y`, the skill's form, priced
        # every cache read as input: a DeepInfra task's real split (616K in, 35.8M cache reads,
        # 129K out) booked $3.61, exact, where its bill was $0.20
        from workbench import models, results, savings
        usage = {"prompt_tokens": 615959 + 35793792, "completion_tokens": 129380,
                 "prompt_tokens_details": {"cached_tokens": 35793792}}
        out = run_wb("model", "price", SPEND_FLASH, "--input", "0.098", "--output", "0.294")
        self.assertIn("your prices, $0.098 in / $0.294 out / $0.00294 cache read / $0 cache write per 1M tokens "
                      "(cache read and write at the catalog's ratio to input: --cache-read, --cache-write to set)", out)
        self.assertEqual(models._overrides()[SPEND_FLASH]["cost"], [{"input": 0.098, "output": 0.294}])
        task = self.api_task("t-io", SPEND_FLASH)
        m = models.lookup(SPEND_FLASH)
        mt = self.meter.for_task(task, m)
        mt.begin(1)
        mt.on_usage(usage)
        self.assertAlmostEqual(mt.total, (615959 * 0.098 + 35793792 * 0.00294 + 129380 * 0.294) / 1e6, places=6)
        self.assertEqual(savings.paid({"kind": "api", "provider": "meterco", "model": SPEND_FLASH,
                                       "api": results.api_usage(task)}), "paid $0.20")
        runner.CURRENT["keyhole"] = types.SimpleNamespace(task=task, model=m)
        catalog = json.loads(runner.write_catalog(task).read_text())  # OpenCode's estimate agrees
        self.assertEqual(catalog["meterco"]["models"]["flash-1"]["cost"]["text"]["input"]["cache"],
                         {"read": 0.00294, "write": 0.0})

