    def test_repo_conf_from_the_main_checkout_reads_an_entry_keyed_on_a_linked_worktree_nested_under_it(self):
        # #1255's review: the git-dir pass skipped every key under the repo's top, so an entry on
        # Claude Code's <repo>/.claude/worktrees/<name> lost its setup from the main checkout
        (self.repo / "pkg").mkdir()
        (self.repo / "pkg" / "a.py").write_text("x = 1\n")
        subprocess.run(["git", "-C", str(self.repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "pkg"], check=True)
        wt = self.repo / ".claude" / "worktrees" / "w"
        subprocess.run(["git", "-C", str(self.repo), "worktree", "add", "-q", "-b", "w", str(wt)],
                       check=True)
        for key, sub in ((wt, None), (wt / "pkg", "pkg")):
            self.conf.write_text(json.dumps({"repos": {str(key): {"setup": "npm ci"}}}))
            self.assertEqual(context.repo_conf(self.repo, sub), {"setup": "npm ci"}, key)
        # and local_only reads it once, from either checkout
        self.conf.write_text(json.dumps({"repos": {str(wt / "pkg"): {"local_only": True}}}))
        self.assertEqual(cli.privacy.local_only(self.repo), str(wt / "pkg"))
        self.conf.write_text(json.dumps({"repos": {str(self.repo / "pkg"): {"local_only": True}}}))
        self.assertEqual(cli.privacy.local_only(wt), str(self.repo / "pkg"))

    def test_a_local_only_key_in_another_letter_case_refuses_an_api_start_where_the_file_system_ignores_case(self):
        # #1157: on macOS's APFS ~/Code/ClientX is ~/code/clientx, but repo_entries compared the
        # real paths as typed, so the key matched nothing and the repo went to the API model
        typed = self.repo.with_name(self.repo.name.swapcase())       # ext4 keeps the two apart
        self.local_only(key=typed)
        self.role(via="api", api=FLASH)
        # case counts where the FS keeps it; on a real APFS (the macOS runners) the key holds
        # unpatched: the test assumed ext4 (nightly run 45362198509, 2026-11-24)
        folds = store.folds_case(self.repo)
        self.assertEqual(cli.privacy.local_only(self.repo), str(typed) if folds else None)
        with mock.patch.object(store, "folds_case", lambda p: True):  # as on APFS
            self.assertEqual(cli.privacy.local_only(self.repo), str(typed))
            code, err = self.fails("start", "t-lo-case", "--spec", str(self.spec), "--repo", str(self.repo))
        self.assertEqual(code, 3)
        self.assertIn("is local-only (commands.json \"repos\")", err)
        self.assertFalse(store.Task("t-lo-case").exists)

    def test_a_local_only_key_in_another_letter_case_holds_for_a_linked_worktree_by_its_git_dir(self):
        # #1157: the git-dir fallback compared the key's git dir (git's relative `.git`, joined to
        # the key as typed) with the worktree's (git's own spelling), so it missed on APFS too
        real = Path(os.path.realpath(self.repo))
        typed = real.with_name(real.name.swapcase())
        wt = Path(self.tmp.name) / "linked"
        subprocess.run(["git", "-C", str(self.repo), "worktree", "add", "-q", "-b", "feat", str(wt)],
                       check=True)
        self.local_only(key=typed)
        common, top = context.gitops.common_dir, context.gitops.toplevel
        on_disk = lambda p: real / Path(p).relative_to(typed) if Path(p).is_relative_to(typed) else p  # noqa: E731

        def as_on_apfs(p):  # the key exists as typed: git finds the repo, its `.git` joined to `p`
            c = common(on_disk(p))
            return typed / c.relative_to(real) if c and Path(p).is_relative_to(typed) else c
        folds = store.folds_case(wt)                                  # a real APFS: held as is
        with mock.patch.object(context.gitops, "common_dir", as_on_apfs), \
                mock.patch.object(context.gitops, "toplevel", lambda p: top(on_disk(p))):
            # case counts where the FS keeps it (nightly run 45362198509, 2026-11-24: not on macOS)
            self.assertEqual(cli.privacy.local_only(wt), str(typed) if folds else None)
            with mock.patch.object(store, "folds_case", lambda p: True):
                self.assertEqual(cli.privacy.local_only(wt), str(typed))

    def test_a_local_only_key_in_another_letter_case_refuses_an_api_start_on_a_folding_mount_under_a_case_sensitive_root(self):
        # #1217: WSL2's /mnt/c folds case below an ext4 root, but folds_case swapped the whole
        # path (/MNT/C/uSERS/…, no /MNT on ext4) and read case-sensitive, so the key missed and
        # the repo went to the API model. drvfs emulated: names below <tmp>/mnt/c fold case
        mount = Path(self.tmp.name) / "mnt" / "c"
        on_disk = mount / "Users" / "Me" / "Code" / "ClientX"
        on_disk.parent.mkdir(parents=True)
        shutil.move(self.repo, on_disk)
        self.repo = on_disk
        typed = mount / "users" / "me" / "code" / "clientx"
        self.local_only(key=typed)
        self.role(via="api", api=FLASH)
        samefile = os.path.samefile

        def as_on_drvfs(a, b):
            below = [os.path.relpath(p, mount) for p in map(os.fspath, (a, b))
                     if p.startswith(str(mount) + os.sep)]
            if len(below) == 2 and below[0].lower() == below[1].lower() and os.path.exists(a):
                return True
            return samefile(a, b)
        with mock.patch("os.path.samefile", as_on_drvfs):
            self.assertTrue(store.folds_case(self.repo))
            self.assertEqual(cli.privacy.local_only(self.repo), str(typed))
            code, err = self.fails("start", "t-lo-drvfs", "--spec", str(self.spec), "--repo", str(self.repo))
        self.assertEqual(code, 3)
        self.assertIn("is local-only (commands.json \"repos\")", err)
        self.assertFalse(store.Task("t-lo-drvfs").exists)

