        self.assertEqual(tail, [": none set up, every role on the GPU",
                                f"  catalog: opencode 1 (free: {cli.FREE_NOTE}) (wb models --api <text> lists ids)"])
        self.catalog(DISCOVERY_CATALOG, DISCOVERY_AUTH)
